local warn, print = function() end, function() end
local reported = false
local function reportError(err)
pcall(function()
if reported then return end
reported = true
local lp = game:GetService("Players").LocalPlayer
local g = Instance.new("ScreenGui")
g.Name = "MarioError"
g.ResetOnSpawn = false
g.DisplayOrder = 999
g.IgnoreGuiInset = true
g.Parent = lp:WaitForChild("PlayerGui")
local f = Instance.new("Frame")
f.Size = UDim2.new(0.92, 0, 0, 230)
f.Position = UDim2.new(0.04, 0, 0, 12)
f.BackgroundColor3 = Color3.fromRGB(120, 10, 10)
f.BorderSizePixel = 0
f.Parent = g
Instance.new("UICorner", f).CornerRadius = UDim.new(0, 10)
local t = Instance.new("TextLabel")
t.Size = UDim2.new(1, -60, 0, 28)
t.Position = UDim2.new(0, 10, 0, 6)
t.BackgroundTransparency = 1
t.TextXAlignment = Enum.TextXAlignment.Left
t.Font = Enum.Font.GothamBold
t.TextSize = 16
t.TextColor3 = Color3.new(1, 1, 1)
t.Text = "MARIO SCRIPT ERROR - copy the text below and send it"
t.Parent = f
local b = Instance.new("TextBox")
b.Size = UDim2.new(1, -20, 1, -48)
b.Position = UDim2.new(0, 10, 0, 38)
b.BackgroundColor3 = Color3.fromRGB(40, 0, 0)
b.TextColor3 = Color3.fromRGB(255, 220, 220)
b.TextXAlignment = Enum.TextXAlignment.Left
b.TextYAlignment = Enum.TextYAlignment.Top
b.Font = Enum.Font.Code
b.TextSize = 14
b.TextWrapped = true
b.MultiLine = true
b.ClearTextOnFocus = false
b.Text = string.sub(tostring(err), 1, 1200)
b.Parent = f
local x = Instance.new("TextButton")
x.Size = UDim2.fromOffset(40, 28)
x.Position = UDim2.new(1, -46, 0, 6)
x.Text = "X"
x.Font = Enum.Font.GothamBold
x.TextSize = 16
x.BackgroundColor3 = Color3.fromRGB(200, 40, 40)
x.TextColor3 = Color3.new(1, 1, 1)
x.Parent = f
x.Activated:Connect(function() g:Destroy() end)
end)
end
-- ================= PURSUITCORE SETTINGS =================
-- Pursuitcore mode is OFF when you start: the script behaves like the normal Mario 64 script.
-- Turn it on in the SM64 menu (scroll down > "Pursuitcore mode"). Then a "PC" button (top right) shows its settings.
-- >>> SET THIS to your GitHub raw folder (must end with /). The two mp3 files sit in that folder.
local MUSIC_BASE = "https://raw.githubusercontent.com/YOUR_USER/YOUR_REPO/main/"
local function musicSrc(name) if string.find(MUSIC_BASE, "YOUR_USER", 1, true) then return name end return MUSIC_BASE .. name end
local PC = shared.PursuitCore
if not PC or PC.version ~= 4 then
PC = {
version = 4,
Enabled = false,         -- false = normal Mario script (always playable Mario, everywhere) | true = Pursuitcore mode
Mode = "auto",           -- "auto" = normal avatar in the lobby, Mario in a match | "game" = always Mario | "lobby" = always normal
Playable = false,        -- false = Mario skin that copies the game's own moves; true = full SM64 moveset
SwapDante = true,        -- Dante becomes Mario
SwapPartyPony = true,    -- Party Pony (the Terminator / killer) becomes Mario
SwapTerminators = false, -- true = EVERY Terminator / killer becomes Mario, not only Party Pony
SwapIcons = true,        -- Dante / Party Pony icons in the menus become the Mario icon
AutoFaces = true,        -- Mario's face changes with what he is doing
MarioSize = 5,           -- height in studs of the Mario that replaces other characters
PuppetFaceFix = math.pi, -- if swapped characters look backwards, change to 0
FaceLock = nil,          -- nil = automatic, or 1-7 to lock one face
UnknownIsGame = true,    -- when the script cannot tell lobby from match: true = Mario, false = normal
UnknownAction = "first_punch", -- Mario move used for a game action the script has no word for (nil = ignore)
ChaseSpeed = 24,         -- running faster than this (studs/s) gives Mario the side-eye face
MusicOn = true,          -- Pursuitcore mode: replace the game music with the two Mario tracks (LMS and chase)
MusicLMS = musicSrc("pc_lms.mp3"),     -- last person standing. Saved by the music installer script (executor workspace folder). Or "rbxassetid://123", or a direct link
MusicChase = musicSrc("pc_chase.mp3"), -- a Terminator is chasing (also saved by the music installer)
MusicVolume = 0.7,
ChaseRange = 60,         -- studs: a Terminator this close (or a User, if you are the Terminator) starts the chase music
RunFaceSpeed = 14,       -- normal mode: running faster than this gives the side-eye face
IsInGame = nil,          -- optional: function(player) return true (match) / false (lobby) end
CustomMatch = nil,       -- optional: function(model) return true end  -> extra characters to swap
}
shared.PursuitCore = PC
end
