local function b64buffer(s)
local buf = buffer.create(#s // 4 * 3)
local o = 0
for i = 1, #s, 4 do
local a1, a2, a3, a4 = s:byte(i, i + 3)
local v = B64[a1] * 262144 + B64[a2] * 4096 + B64[a3] * 64 + B64[a4]
buffer.writeu8(buf, o, v // 65536); buffer.writeu8(buf, o + 1, (v // 256) % 256); buffer.writeu8(buf, o + 2, v % 256)
o += 3
end
return buf
end
local function u16(b, o) return buffer.readu8(b, o) * 256 + buffer.readu8(b, o + 1) end
local function s16(b, o) local x = u16(b, o); if x >= 32768 then x -= 65536 end return x end
