local pal = {}
for i = 0, #TEX_PALETTE / 6 - 1 do
local h = TEX_PALETTE:sub(i * 6 + 1, i * 6 + 6)
local r, g, b = tonumber(h:sub(1, 2), 16), tonumber(h:sub(3, 4), 16), tonumber(h:sub(5, 6), 16)
if metal then
local l = (r * 0.3 + g * 0.59 + b * 0.11) / 255
l = math.clamp((l - 0.5) * 1.3 + 0.55, 0.1, 1)
r, g, b = math.floor(l * 205), math.floor(l * 214), math.floor(l * 236)
end
pal[i] = { r, g, b }
end
local buf = buffer.create(TEX_N * TEX_N * 4)
local p = 0
for i = 1, #TEX_RLE, 3 do
local c = pal[lut[TEX_RLE:sub(i, i)]]
local len = lut[TEX_RLE:sub(i + 1, i + 1)] * 64 + lut[TEX_RLE:sub(i + 2, i + 2)] + 1
for _ = 1, len do
buffer.writeu8(buf, p, c[1]); buffer.writeu8(buf, p + 1, c[2])
buffer.writeu8(buf, p + 2, c[3]); buffer.writeu8(buf, p + 3, 255)
