local em = AssetService:CreateEditableMesh()
local nv = u16(buf, o); o += 2
local vid = {}
for i = 1, nv do
vid[i] = em:AddVertex(Vector3.new(s16(buf, o) / 20000 * S, s16(buf, o + 2) / 20000 * S, s16(buf, o + 4) / 20000 * S))
o += 6
