local nuv = u16(buf, o); o += 2
local uid = {}
for i = 1, nuv do
local u, v = u16(buf, o) / 65535, u16(buf, o + 2) / 65535
if CFG.FlipV then v = 1 - v end
uid[i] = em:AddUV(Vector2.new(u, v))
o += 4
end
local nn = u16(buf, o); o += 2
local nid = {}
for i = 1, nn do
nid[i] = em:AddNormal(Vector3.new(s8(buf, o) / 127, s8(buf, o + 1) / 127, s8(buf, o + 2) / 127).Unit)
o += 3
end
local nt = u16(buf, o); o += 2
for _ = 1, nt do
local va, ua, na = u16(buf, o) + 1, u16(buf, o + 2) + 1, u16(buf, o + 4) + 1
local vb, ub, nb = u16(buf, o + 6) + 1, u16(buf, o + 8) + 1, u16(buf, o + 10) + 1
local vc, uc, nc = u16(buf, o + 12) + 1, u16(buf, o + 14) + 1, u16(buf, o + 16) + 1
o += 18
local f = em:AddTriangle(vid[va], vid[vb], vid[vc])
em:SetFaceUVs(f, { uid[ua], uid[ub], uid[uc] })
em:SetFaceNormals(f, { nid[na], nid[nb], nid[nc] })
