local pos = Vector3.new(posA.X + (posB.X - posA.X) * alpha, posA.Y + (posB.Y - posA.Y) * alpha, posA.Z + (posB.Z - posA.Z) * alpha)
for j = 1, #ROT do pose[j] = kA[j]:Lerp(kB[j], alpha) end
lastPose, lastPos = table.clone(pose), pos
if blendFrom and blendT < 1 then
blendT += dt / blendDur
local w = math.clamp(blendT, 0, 1)
for j = 1, #ROT do pose[j] = blendFrom[j]:Lerp(pose[j], w) end
pos = blendFromPos:Lerp(pos, w)
if blendT >= 1 then blendFrom = nil end
end
local tilt = CFrame.fromAxisAngle(CFG.TiltForwardAxis, tiltPitch * CFG.TiltForwardSign)
* CFrame.fromAxisAngle(CFG.TiltSideAxis, tiltRoll * CFG.TiltSideSign)
for j = 1, #ROT do
local cf
if j == 1 then cf = CFrame.new(pos) * CFrame.fromAxisAngle(CFG.BodyPitchAxis, bodyPitch * CFG.BodyPitchSign) * pose[j]
elseif ROT[j] == "Torso" then cf = CFrame.new(nodeT[j]) * tilt * pose[j]
else cf = CFrame.new(nodeT[j]) * pose[j] end
motors[j].C0 = baseC0[j] * cf
end
end
