local function setSize(h)
local r = h / CFG.ModelHeight
if math.abs(r - 1) < 1e-4 then return end
CFG.ModelHeight = h
S = S * r
groundAdj = groundAdj * r
posScale = S
for _, d in ipairs(marioModel:GetChildren()) do
if d:IsA("BasePart") then d.Size = d.Size * r end
end
for _, d in ipairs(marioModel:GetDescendants()) do
if d:IsA("Weld") then d.C0 = (d.C0 - d.C0.Position) + d.C0.Position * r end
end
for k, v in pairs(center) do center[k] = v * r end
for j, n in ipairs(ROT) do
nodeT[j] = nodeT[j] * r
local m = motors[j]
if n == "Body" then
m.C0 = bodyC0()
m.C1 = CFrame.new(-center[n])
else
m.C0 = CFrame.new(-center[PARENT[n]])
m.C1 = CFrame.new(-center[n])
end
baseC0[j] = m.C0
end
end
