local function getMove()
local mv = controls:GetMoveVector()
if mv.Magnitude < 0.05 then return Vector3.zero, 0 end
local cf = workspace.CurrentCamera.CFrame
local f = flat(cf.LookVector)
if f.Magnitude < 0.01 then f = flat(cf.UpVector) end
f = f.Unit
local r = f:Cross(Vector3.yAxis)
local d = r * mv.X + f * (-mv.Z)
if d.Magnitude < 0.01 then return Vector3.zero, 0 end
return d.Unit, math.min(mv.Magnitude, 1)
end
