-- SM64 numbers: Mario's hurtbox is a cylinder of radius 37 and height 160 (SM64 units).
-- 160 SM64 units = CFG.ModelHeight studs. Attacks hit anything whose hurtbox touches Mario's
-- radius + a short attack reach, inside a forward arc (like the real game's attack-angle check).
local ATTACK = {
punch = { 40, 60 }, kick = { 40, 60 }, slide = { 40, 100 }, air = { 40, 100 }, dive = { 40, 100 }, pound = { 110, 360 },
}
local HB = { h = 160 }
local function hitbox(_center, _radius, dmg, kind)
local u = CFG.ModelHeight / 160
if HB.flash then pcall(HB.flash, kind) end
local rule = ATTACK[kind] or { 40, 90 }
local reach = 37 * u + rule[1] * u
local mpos = root.Position
local feetY = mpos.Y - rigFeet()
local topY = feetY + HB.h * u
local fwd = dirOf(faceYaw)
local seen = {}
for _, p in ipairs(workspace:GetPartBoundsInRadius(mpos, reach + 8, overlapParams)) do
local m = p:FindFirstAncestorOfClass("Model")
if m and not seen[m] then
seen[m] = true
local h = m:FindFirstChildOfClass("Humanoid")
local hrp = m:FindFirstChild("HumanoidRootPart")
if h and hrp and h.Health > 0 and not hitSet[h] and not Players:GetPlayerFromCharacter(m) then
local cf, size = m:GetBoundingBox()
local tr = math.min(math.max(hrp.Size.X, hrp.Size.Z) / 2, 2)
local d = flat(hrp.Position - mpos)
local dist = d.Magnitude
local lowY, highY = cf.Position.Y - size.Y / 2, cf.Position.Y + size.Y / 2
local inArc = rule[2] >= 360 or dist < 0.2 or math.acos(math.clamp(fwd:Dot(d.Unit), -1, 1)) <= math.rad(rule[2])
if dist <= reach + tr and lowY <= topY and highY >= feetY and inArc then
hitSet[h] = true
dealHit(h, m, dmg, kind)
end
end
end
end
end
local function front(dist) return root.Position + dirOf(faceYaw) * dist end
local lastLJ, ljDir, ljBack = -10, 0, false
