local function launch(kind, vy, newHv, face)
hv = newHv
if face then faceYaw = face end
root.AssemblyLinearVelocity = Vector3.new(hv.X, vy, hv.Z)
launchGrace = 0.12
humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
setState(kind)
jumpCut = false
eat("jump")
local an = AIR_ANIM[kind] or "general_fall"
local sp = 1
if FIT[kind] then
sp = math.clamp(trackLength(an, 1) / math.max(2 * vy / (CFG.GravityScale * workspace.Gravity), 0.2), 0.6, 2)
end
play(an, sp, 0.05)
end
local function doJump()
local dirv = dirOf(moveYaw)
local mvIn, mgIn = getMove()
local pushFwd = mgIn > 0.1 and mvIn:Dot(dirOf(ljFace)) > 0.5
if os.clock() - lastLJ < 0.9 and (state == "Land" or state == "Crouch" or state == "Crawl") and not pushFwd then
-- backwards long jump: keep facing the long-jump direction, travel the opposite way
ljBack = true
if bljStuck then bljSpeed = math.min(CFG.BLJMax, bljSpeed * CFG.BLJGrow + CFG.BLJAdd) else bljSpeed = CFG.LongJumpSpeed end
bljStuck = false
launch("LongJump", CFG.LongJumpV, -dirOf(ljFace) * bljSpeed, ljFace)
play("slow_longjump", 1, 0.05)
return
end
if state == "Crouch" or state == "Crawl" then
if fVel > CFG.LongJumpMin then
ljBack = false
ljFace, bljStuck = moveYaw, false
launch("LongJump", CFG.LongJumpV, dirv * math.max(fVel, CFG.LongJumpSpeed), moveYaw)
else
launch("Backflip", CFG.BackflipV, -dirOf(faceYaw) * CFG.BackflipBack, faceYaw)
end
elseif state == "Skid" then
launch("SideFlip", CFG.SideFlipV, dirOf(skidFace) * CFG.SideFlipSpeed, skidFace)
else
local n = 1
if os.clock() - lastLand < CFG.ChainWindow then
n = chainAfter + 1
if chainAfter == 3 then n = 3
elseif n == 3 and fVel < CFG.TripleMin then n = 2 end
end
local fwd = dirv * fVel * 0.92
if n == 1 then launch("Jump", CFG.JumpV, fwd, faceYaw)
elseif n == 2 then launch("DoubleJump", CFG.DoubleV, fwd, faceYaw)
else launch("TripleJump", CFG.TripleV, fwd * 1.1, faceYaw) end
end
end
local function onLand()
local from = state
diveCancelT = 0
local h = flat(hv)
moveYaw = h.Magnitude > 1 and yawOf(h) or faceYaw
fVel = h.Magnitude
hv = Vector3.zero
lastLand = os.clock()
chainAfter = (from == "Jump" and 1) or (from == "DoubleJump" and 2) or (from == "GroundPound" and 3) or 0
landAnim, landLock, landFreeze, landFriction = "general_land", 0.12, false, 80
if from == "Jump" then landAnim = "land_from_single_jump"
elseif from == "DoubleJump" then landAnim = "land_from_double_jump"
elseif from == "WallKick" then
landAnim = "wall_kick_land"
elseif from == "SideFlip" then
landAnim, landLock, landFreeze, landFriction = "slideflip_alt", 0.45, true, 60
fVel = fVel * 0.3
elseif from == "TripleJump" then
landAnim, landLock, landFreeze = "triple_jump_land", 0.5, true
fVel = fVel * 0.4
elseif from == "Backflip" then
landAnim, landLock, landFreeze = "backflip_land", 0.4, true
fVel = 0
elseif from == "LongJump" then
lastLJ, ljDir = os.clock(), ljFace
landAnim, landLock, landFriction = "crouch_from_fast_longjump", 0.55, 30
fVel = fVel * 0.75
if ljBack then
if stateTime < 0.25 then bljStuck = true end -- landed almost at once (low ceiling / stairs): keep building speed
fVel = 0
end
elseif from == "Dive" then
fVel = math.min(fVel, 34)
setState("DiveSlide")
play("dive_hold", 1, 0.05)
return
elseif from == "GroundPound" then
landAnim, landLock, landFreeze = "ground_pound_landing", 0.5, true
fVel = 0
setState("Land")
hitbox(root.Position, 9, CFG.Damage.pound, "pound")
play(landAnim, 1, 0.03)
return
end
if not landFreeze then landLock = math.max(landLock, math.min(0.6, trackLength(landAnim, 0) * 0.85)) end
setState("Land")
play(landAnim, 1, 0.03)
end
local carried, carryWeld, carryInfo = nil, nil, nil
local function isNPC(m)
if not m or m == character then return false end
if Players:GetPlayerFromCharacter(m) then return false end
local h = m:FindFirstChildOfClass("Humanoid")
return h ~= nil and h.Health > 0 and m:FindFirstChild("HumanoidRootPart") ~= nil
end
local function releaseCarried(vel)
if not carried then return end
local m, info = carried, carryInfo
carried, carryInfo = nil, nil
if carryWeld then carryWeld:Destroy(); carryWeld = nil end
if m.Parent then
for part, v in pairs(info.parts) do
if part.Parent then part.CanCollide = v.cc; part.Massless = v.ms end
end
local hrp = m:FindFirstChild("HumanoidRootPart")
if hrp then
hrp.Anchored = info.anch
hrp.AssemblyLinearVelocity = vel or Vector3.zero
end
local h = m:FindFirstChildOfClass("Humanoid")
if h then
h.PlatformStand = info.ps
h:ChangeState(Enum.HumanoidStateType.GettingUp)
end
end
end
local function grabNearest()
local best, bd = nil, 99
for _, part in ipairs(workspace:GetPartBoundsInRadius(front(2.2), 4.5, overlapParams)) do
local m = part:FindFirstAncestorOfClass("Model")
if m and isNPC(m) then
local d = (m.HumanoidRootPart.Position - root.Position).Magnitude
if d < bd then best, bd = m, d end
end
end
if not best then return false end
local hrp = best.HumanoidRootPart
local h = best:FindFirstChildOfClass("Humanoid")
local info = { parts = {}, anch = hrp.Anchored, ps = h.PlatformStand }
for _, d in ipairs(best:GetDescendants()) do
if d:IsA("BasePart") then
info.parts[d] = { cc = d.CanCollide, ms = d.Massless }
d.CanCollide = false; d.Massless = true
end
end
h.PlatformStand = true
hrp.Anchored = false
hrp.AssemblyLinearVelocity = Vector3.zero
hrp.CFrame = root.CFrame * CFrame.new(0, CFG.ModelHeight * 0.85, 0)
local w = Instance.new("WeldConstraint")
w.Part0 = root; w.Part1 = hrp; w.Parent = hrp
carried, carryWeld, carryInfo = best, w, info
return true
end
local function throwCarried()
if not carried then return end
releaseCarried(dirOf(faceYaw) * 55 + Vector3.new(0, 28, 0))
play("throw_npc", 1.1, 0.04)
end
local function toggleCarry()
if carried then
releaseCarried(dirOf(faceYaw) * 6)
elseif state == "Idle" or state == "Walk" then
grabNearest()
end
end
local function startAttack()
eat("attack")
if carried then throwCarried() return end
if state == "Idle" or state == "Walk" then
if state == "Walk" and fVel >= CFG.SlideKickMin then
fVel = math.max(fVel, CFG.SlideKickSpeed)
faceYaw = moveYaw
setState("SlideKick")
play("slide_kick", 1, 0.04)
else
comboQueued = false
setState("Punch1")
fVel = CFG.PunchLunge
moveYaw = faceYaw
play("first_punch", 1.2, 0.04)
end
elseif AIR[state] and state ~= "AirKick" and state ~= "Dive" and state ~= "GPStart"
and state ~= "GroundPound" and state ~= "AirBonk" then
local speed = flat(hv).Magnitude
if speed >= CFG.DiveMinSpeed then
local d = flat(hv).Unit
launch("Dive", CFG.DiveV, d * math.max(speed, CFG.DiveSpeed), yawOf(d))
else
local saved = hv
local vy = root.AssemblyLinearVelocity.Y
setState("AirKick")
hv = saved
root.AssemblyLinearVelocity = Vector3.new(hv.X, math.max(vy, 8), hv.Z)
play("air_kick", 1.9, 0.04)
end
end
end
local function locomote(dt, mag, wantYaw, maxSpeed, friction)
local skid = false
if wantYaw then
local d = angDiff(moveYaw, wantYaw)
if state == "Walk" and fVel > CFG.SkidSpeed and math.abs(d) > math.rad(115) then
skid = true
skidFace = wantYaw
else
local turn = math.rad(lerp(CFG.TurnSlow, CFG.TurnFast, math.clamp(fVel / CFG.RunMax, 0, 1))) * dt
local stepYaw = math.clamp(d, -turn, turn)
moveYaw += stepYaw
turnRate = stepYaw / dt
local target = maxSpeed * mag
if fVel < target then
fVel = math.min(target, fVel + CFG.Accel * dt * (1.6 - fVel / math.max(maxSpeed, 1)))
else
fVel = math.max(target, fVel - friction * dt)
end
end
else
turnRate = 0
if state == "Walk" and fVel > CFG.BrakeSkidSpeed then
skid = true
skidFace = moveYaw
end
fVel = math.max(0, fVel - friction * dt)
end
faceYaw = moveYaw
return skid
end
local function wallRay(dir, len)
local res = workspace:Raycast(root.Position, dir * len, rayParams)
if res and math.abs(res.Normal.Y) < 0.35 then return res end
return nil
end
local slideBlock, slideAng = 0, 0
local ledgeBlock, ledgeNormal, ledgeRoot, ledgeOrigin, ledgeFast = 0, Vector3.zero, Vector3.zero, Vector3.zero, true
local function feetOffset()
return rigFeet()
end
local function tryLedge()
local H, fo = CFG.ModelHeight, feetOffset()
local pos = root.Position
local feetY = pos.Y - fo
local d = dirOf(faceYaw)
local wall = workspace:Raycast(Vector3.new(pos.X, feetY + H * 0.5, pos.Z), d * 2.2, rayParams)
if not wall or math.abs(wall.Normal.Y) > 0.3 then return false end
local n = flat(wall.Normal)
if n.Magnitude < 0.1 then return false end
n = n.Unit
if n:Dot(d) > -0.5 then return false end
local spot = wall.Position - n * 0.6
local down = workspace:Raycast(Vector3.new(spot.X, feetY + H * 1.05, spot.Z), Vector3.new(0, -H * 0.46, 0), rayParams)
if not down or down.Normal.Y < 0.9 then return false end
if workspace:Raycast(down.Position + Vector3.new(0, 0.2, 0), Vector3.new(0, H * 0.9, 0), rayParams) then return false end
ledgeNormal, ledgeOrigin = n, down.Position
ledgeRoot = down.Position + Vector3.new(0, fo + 0.1, 0)
faceYaw = yawOf(-n)
moveYaw = faceYaw
hv = Vector3.zero
fVel = 0
root.CFrame = CFrame.new(ledgeRoot) * CFrame.Angles(0, faceYaw, 0)
root.AssemblyLinearVelocity = Vector3.zero
setState("Ledge")
play("ledge_idle", 1, 0.05)
return true
end
local function letGoLedge()
local rp = ledgeOrigin + ledgeNormal * 1.2 + Vector3.new(0, feetOffset() - CFG.ModelHeight * 0.9, 0)
root.CFrame = CFrame.new(rp) * CFrame.Angles(0, faceYaw, 0)
ledgeBlock = os.clock() + 0.5
launch("Fall", 0, ledgeNormal * 3)
end
local FXS = { wing = player:GetAttribute("M64Wing") == true, metal = player:GetAttribute("M64Metal") == true, gliding = false, wasGliding = false, lastFlap = -10,
glide = { Jump = true, DoubleJump = true, TripleJump = true, Fall = true, SideFlip = true, Backflip = true, LongJump = true } }
local NOPITCH = { LongJump = true, AirKick = true, GPStart = true, GroundPound = true, Backflip = true, TripleJump = true, SideFlip = true, AirBonk = true, WallKick = true }
local function step(dt)
if carried then
local ch = carried:FindFirstChildOfClass("Humanoid")
if not carried.Parent or not ch or ch.Health <= 0 or humanoid.Health <= 0 then releaseCarried(Vector3.zero) end
end
if grabRequest then grabRequest = false; toggleCarry() end
if dead then return end
dt = math.min(dt, 0.05)
if debugMode then
humanoid:Move(Vector3.zero, false)
humanoid.WalkSpeed = 0.01
return
end
stateTime += dt
local t = os.clock()
local cur = root.AssemblyLinearVelocity
local move, mag = getMove()
local wantYaw = mag > 0.1 and yawOf(move) or nil
if launchGrace > 0 then launchGrace -= dt end
local floor = humanoid.FloorMaterial ~= Enum.Material.Air and launchGrace <= 0
if floor then airTime = 0 else airTime += dt end
local swimming = humanoid:GetState() == Enum.HumanoidStateType.Swimming
if swimming and state ~= "Swim" then
hv = Vector3.zero
fVel = 0
setState("Swim")
elseif not swimming and state == "Swim" then
setState("Idle")
end
if AIR[state] then
if floor and cur.Y < 5 then onLand() end
elseif not floor and airTime > 0.12 and state ~= "Bonk" and state ~= "Swim" and state ~= "Ledge" and state ~= "LedgeClimb" then
hv = dirOf(moveYaw) * fVel
setState("Fall")
play("general_fall")
end
if AIR[state] then
humanoid:Move(Vector3.zero, false)
local vy = cur.Y
if diveCancelT > 0 then
diveCancelT -= dt
faceYaw = diveCancelYaw
end
if fresh("crouch") and state ~= "GPStart" and state ~= "GroundPound" and state ~= "AirBonk" then
eat("crouch")
hv = Vector3.zero
local flying = state == "TripleJump"
setState("GPStart")
play(flying and "start_ground_pound_flying" or "start_ground_pound", 1, 0.04)
vy = 0
end
if fresh("attack") then startAttack() end
if state == "Dive" and fresh("jump", 0.3) and stateTime > 0.04 then
eat("jump")
-- clean dive cancel: keep facing + momentum, stand back up smoothly (no snap-turn)
diveCancelT, diveCancelYaw = 0.5, faceYaw
setState("Fall")
play("general_fall", 1, 0.22)
end
vy = state == "GPStart" and 0 or root.AssemblyLinearVelocity.Y
if state == "GPStart" then
hv = Vector3.zero
vy = 0
if stateTime >= (sm64Gravity and 0.37 or CFG.GPHover) then
setState("GroundPound")
end
elseif state == "GroundPound" then
hv = Vector3.zero
vy = sm64Gravity and -(50 * 30 * CFG.ModelHeight / 160) or -CFG.GPSpeed
else
if not NO_STEER[state] and diveCancelT <= 0 then
if wantYaw then
hv += move * CFG.AirAccel * mag * dt
local s = hv.Magnitude
if s > CFG.AirMax and s > 0 then
hv = hv.Unit * math.max(CFG.AirMax, s - 30 * dt)
end
else
hv *= (1 - math.min(CFG.AirDrag * dt, 1))
end
end
if state == "LongJump" and diveCancelT <= 0 then
-- long jump: facing stays locked; slowly steering the movement backwards turns it into a BLJ
local cur = flat(hv)
local sp = cur.Magnitude
if wantYaw and sp > 1 then
local cy = yawOf(cur)
local d = angDiff(cy, wantYaw)
local lim = math.rad(110) * mag * dt
hv = dirOf(cy + math.clamp(d, -lim, lim)) * sp
end
local dotv = flat(hv):Dot(dirOf(ljFace))
if not ljBack and dotv < -2 then
ljBack = true
bljSpeed, bljStuck = math.max(CFG.LongJumpSpeed, flat(hv).Magnitude), false
play("slow_longjump", 1, 0.15)
elseif ljBack and dotv > 2 then
ljBack = false
play(AIR_ANIM.LongJump, 1, 0.15)
end
faceYaw = ljFace
if ljBack and workspace:Raycast(root.Position, Vector3.new(0, CFG.ModelHeight * CFG.BLJCeil, 0), rayParams) then
bljStuck = true -- head under a low ceiling: short hops, speed keeps stacking
end
end
if sm64Gravity then
local U = CFG.ModelHeight / 160
local g = ((state == "LongJump") and 2 or 4) * 900 * U
vy = math.max(vy + (workspace.Gravity - g) * dt, -75 * 30 * U)
else
vy += (1 - CFG.GravityScale) * workspace.Gravity * dt
end
if (state == "Jump" or state == "DoubleJump") and vy > 0 and not jumpCut and not jumpHeld() then
vy *= 0.45
jumpCut = true
end
if state == "DoubleJump" and vy < 0 and not FXS.gliding then play("double_jump_fall") end
if state == "AirKick" and stateTime > 0.45 then setState("Fall"); play("general_fall") end
end
if state == "AirKick" then hitbox(front(2.5), 3.6, CFG.Damage.air, "air") end
if state == "Dive" then hitbox(front(2.2), 3.4, CFG.Damage.dive, "dive") end
local hs = flat(hv)
if state ~= "GPStart" and state ~= "GroundPound" then
local dir = hs.Magnitude > 3 and hs.Unit or dirOf(faceYaw)
local hit = wallRay(dir, 2.7)
if hit then
lastWall, wallNormal = t, flat(hit.Normal).Unit
if state == "LongJump" and ljBack then bljStuck = true end
if state == "Dive" or (state == "LongJump" and not ljBack and hs.Magnitude > 30) then
hv = wallNormal * 9
vy = 0
setState("AirBonk")
play("backward_air_kb", 1.5, 0.03)
else
hv = hs - hs:Dot(wallNormal) * wallNormal
end
end
if fresh("jump") and t - lastWall < 0.22 and wallNormal.Magnitude > 0 and not (state == "LongJump" and ljBack) then
launch("WallKick", CFG.WallKickV, wallNormal * CFG.WallKickSpeed, yawOf(wallNormal))
vy = CFG.WallKickV
end
end
if t > ledgeBlock and vy <= 0 and AIR[state] and not carried and state ~= "Dive" and state ~= "GPStart" and state ~= "GroundPound" and state ~= "AirBonk" and state ~= "AirKick" and not (state == "LongJump" and ljBack) then
if tryLedge() then vy = 0 end
end
local hs2 = flat(hv)
if not KEEP_FACE[state] and state ~= "LongJump" and hs2.Magnitude > 2 and diveCancelT <= 0 then
local d = angDiff(faceYaw, yawOf(hs2))
faceYaw += math.clamp(d, -math.rad(720) * dt, math.rad(720) * dt)
end
FXS.gliding = false
if FXS.wing and not carried and FXS.glide[state] and stateTime > 0.18 and vy < 8 and jumpHeld() then
FXS.gliding = true
if fresh("jump") and t - FXS.lastFlap > 0.4 then
eat("jump")
FXS.lastFlap = t
vy = 26
if FXS.onFlap then FXS.onFlap() end
end
vy = math.max(vy, -14)
hv += dirOf(faceYaw) * 45 * dt
local gs = flat(hv)
local gcap = CFG.RunMax * 1.15
if gs.Magnitude > gcap then hv = gs.Unit * gcap end
play("flying", 1, 0.15)
elseif FXS.wasGliding and AIR[state] then
play("general_fall", 1, 0.15)
end
FXS.wasGliding = FXS.gliding
root.AssemblyLinearVelocity = Vector3.new(hv.X, vy, hv.Z)
else
if floor and t > slideBlock and (state == "Idle" or state == "Walk" or state == "Crouch" or state == "Crawl" or state == "Skid" or state == "Land" or state == "DiveSlide" or state == "SlideKick" or state == "Bonk") then
local fh = workspace:Raycast(root.Position, Vector3.new(0, -(feetOffset() + 2.5), 0), rayParams)
if fh and fh.Normal.Y < math.cos(math.rad(CFG.SlideAngle)) then
local fd = flat(Vector3.new(0, -1, 0) + fh.Normal * fh.Normal.Y)
if fd.Magnitude > 0.05 then
fd = fd.Unit
local downhillWalk = state == "Walk" and wantYaw ~= nil and dirOf(wantYaw):Dot(fd) > 0.5
if not downhillWalk then
moveYaw = yawOf(fd)
faceYaw = moveYaw
fVel = math.max(math.min(fVel, 30) * 0.5, 8)
setState("Slide")
play("slide_sit", 1, 0.08)
end
end
end
end
if emoteRequest and (state == "Idle") then
local e = emoteRequest
emoteRequest = nil
setState("Emote")
emoteLen = LOOPED[e] and math.max(trackLength(e, 3), 3) or trackLength(e, 3)
fVel = 0
play(e, 1, 0.15)
end
emoteRequest = nil
if state == "Idle" or state == "Walk" or state == "Crouch" or state == "Crawl" or state == "Emote" then
if state == "Emote" and (wantYaw or fresh("jump") or fresh("attack") or stateTime > emoteLen) then
setState("Idle")
end
if fresh("jump") and state ~= "Emote" then
doJump()
elseif fresh("attack") and not held.crouch and state ~= "Emote" then
startAttack()
elseif state == "Emote" then
groundDrive(0, faceYaw)
else
local crouching = held.crouch
local maxSpeed = crouching and CFG.CrawlMax or (held.walk and CFG.WalkMax or CFG.RunMax)
local friction = crouching and 40 or CFG.Friction
local skid = locomote(dt, mag, wantYaw, maxSpeed, friction)
if skid then
setState("Skid")
play("skid_on_ground", 1, 0.05)
else
if state == "Walk" and fVel >= CFG.BonkSpeed then
local hit = wallRay(dirOf(faceYaw), 2.7)
if hit and flat(hit.Normal).Magnitude > 0.1
and dirOf(faceYaw):Dot(-flat(hit.Normal).Unit) > 0.7 then
fVel = 16
setState("Bonk")
play("ground_bonk", 1.6, 0.03)
end
end
if state ~= "Bonk" then
local moving = fVel > 0.5 or wantYaw ~= nil
local newState
if crouching then newState = (moving and "Crawl" or "Crouch")
else newState = (moving and "Walk" or "Idle") end
if state ~= newState then
local prev = state
local prevLow = prev == "Crouch" or prev == "Crawl"
if (newState == "Crouch" or newState == "Crawl") and not prevLow then
play("start_crouching", 1, 0.05)
elseif newState == "Crawl" and prev == "Crouch" then
play("start_crawling", 1.3, 0.05)
elseif newState == "Crouch" and prev == "Crawl" then
play("stop_crawling", 1.3, 0.05)
elseif newState == "Idle" and prevLow then
play("stop_crouching", 1.2, 0.05)
end
setState(newState)
end
if newState == "Idle" then
idleTime += dt
groundDrive(0, faceYaw)
if not busy() then
if carried then play("hold_idle", 1, 0.15)
elseif idleTime > CFG.SleepAfter then
lookIdx = 0
play("sleep_idle", 1, 0.2)
else
idleAnim()
end
end
else
idleTime = 0
nextLook = 5
groundDrive(fVel, moveYaw)
if newState == "Crouch" then
if not busy() then play("crouching") end
elseif newState == "Crawl" then
if not busy() then play("crawling", math.clamp(fVel / 5.5, 0.6, 2.5)) end
elseif carried then play(fVel < CFG.RunAnimAbove and "hold_walk" or "hold_run", sm64Rate(fVel))
elseif fVel < CFG.TipToeBelow then play("tiptoe", sm64Rate(fVel))
elseif fVel < CFG.SlowWalkBelow then play("slow_walk", sm64Rate(fVel))
elseif fVel < CFG.RunAnimAbove then play("walking", sm64Rate(fVel))
else play("running", sm64Rate(fVel)) end
end
end
end
if state ~= "Idle" then idleTime = 0 end
end
elseif state == "Skid" then
fVel = math.max(0, fVel - CFG.SkidFriction * dt)
if wantYaw then skidFace = wantYaw end
if fVel < 10 then
faceYaw += math.clamp(angDiff(faceYaw, skidFace), -math.rad(720) * dt, math.rad(720) * dt)
else
faceYaw = moveYaw
end
groundDrive(fVel, moveYaw)
if fresh("jump") then
doJump()
elseif wantYaw and fVel < 20 and math.abs(angDiff(moveYaw, wantYaw)) < math.rad(60) then
setState("Walk")
elseif fVel <= 3 and stateTime > 0.2 then
faceYaw = skidFace
moveYaw = skidFace
if wantYaw then
fVel = 6
setState("Walk")
else
fVel = 0
setState("Idle")
end
end
elseif state == "Slide" then
local fh = workspace:Raycast(root.Position, Vector3.new(0, -(feetOffset() + 2.5), 0), rayParams)
local ang = fh and math.acos(math.clamp(fh.Normal.Y, -1, 1)) or 0
slideAng = ang
local steep = fh ~= nil and ang > math.rad(CFG.SlideAngle - 4)
if steep then
local fd = flat(Vector3.new(0, -1, 0) + fh.Normal * fh.Normal.Y)
if fd.Magnitude > 0.05 then
local yd = yawOf(fd.Unit)
local target = wantYaw and (yd + math.clamp(angDiff(yd, wantYaw), -math.rad(75), math.rad(75))) or yd
moveYaw += math.clamp(angDiff(moveYaw, target), -math.rad(140) * dt, math.rad(140) * dt)
end
