slideBlock = t + 0.4
doJump()
elseif not steep and fVel < 3 then
fVel = 0
landAnim, landLock, landFreeze, landFriction = "stand_up_from_slide", 0.5, true, 80
setState("Land")
play(landAnim, 1, 0.05)
end
elseif state == "Ledge" then
hv = Vector3.zero; fVel = 0
humanoid:Move(Vector3.zero, false)
root.CFrame = CFrame.new(ledgeRoot) * CFrame.Angles(0, faceYaw, 0)
root.AssemblyLinearVelocity = Vector3.zero
local away = wantYaw ~= nil and math.abs(angDiff(wantYaw, yawOf(ledgeNormal))) < math.rad(100)
if fresh("crouch") or (away and stateTime > 0.2) then
eat("crouch")
letGoLedge()
elseif fresh("jump") and stateTime > 0.1 then
eat("jump")
ledgeFast = true
setState("LedgeClimb")
play("ledge_grab_fast", 1, 0.03)
elseif wantYaw and stateTime > 0.35 then
ledgeFast = false
setState("LedgeClimb")
play("ledge_grab_slow", 1, 0.03)
end
elseif state == "LedgeClimb" then
hv = Vector3.zero; fVel = 0
humanoid:Move(Vector3.zero, false)
root.CFrame = CFrame.new(ledgeRoot) * CFrame.Angles(0, faceYaw, 0)
root.AssemblyLinearVelocity = Vector3.zero
if stateTime >= trackLength(ledgeFast and "ledge_grab_fast" or "ledge_grab_slow", 0.7) then
moveYaw = faceYaw
setState("Idle")
play("idle", 1, 0.1)
end
elseif state == "Land" then
fVel = math.max(0, fVel - landFriction * dt)
groundDrive(fVel, moveYaw)
if fresh("jump") and (not landFreeze or stateTime > 0.15) then
doJump()
elseif stateTime >= landLock or (not landFreeze and wantYaw and stateTime > 0.06) then
setState(fVel > 0.5 and "Walk" or "Idle")
end
elseif state == "Punch1" or state == "Punch2" or state == "Kick" then
fVel = math.max(0, fVel - 40 * dt)
groundDrive(fVel, faceYaw)
if stateTime > 0.06 and stateTime < (state == "Kick" and 0.5 or 0.28) then
local kind = state == "Kick" and "kick" or "punch"
hitbox(front(2.4), CFG.PunchRadius, CFG.Damage[kind], kind)
end
if stateTime > 0.1 and fresh("attack") then
comboQueued = true
eat("attack")
end
local dur = state == "Kick" and 0.75 or 0.4
if stateTime >= dur then
if comboQueued and state == "Punch1" then
comboQueued = false
setState("Punch2"); fVel = CFG.PunchLunge
play("second_punch", 1.2, 0.04)
elseif comboQueued and state == "Punch2" then
comboQueued = false
setState("Kick"); fVel = CFG.PunchLunge + 3
play("ground_kick", 1.4, 0.04)
else
comboQueued = false
setState("Idle")
end
end
elseif state == "SlideKick" then
fVel = math.max(0, fVel - CFG.SlideKickFriction * dt)
groundDrive(fVel, moveYaw)
hitbox(front(2.6), 4, CFG.Damage.slide, "slide")
if stateTime > 0.7 or fVel < 4 then
landAnim, landLock, landFreeze, landFriction = "crouch_from_slide_kick", 0.5, false, 50
setState("Land")
play(landAnim, 1, 0.05)
end
elseif state == "DiveSlide" then
fVel = math.max(0, fVel - CFG.DiveSlideFriction * dt)
faceYaw = moveYaw
groundDrive(fVel, moveYaw)
if fresh("jump") then
launch("Dive", CFG.DiveHopV, dirOf(moveYaw) * math.max(fVel, CFG.DiveHopSpeed), moveYaw)
elseif fVel < 2 then
landAnim, landLock, landFreeze, landFriction = "slow_land_from_dive", 1.1, false, 80
fVel = 0
setState("Land")
play(landAnim, 1, 0.05)
end
elseif state == "Bonk" then
fVel = math.max(0, fVel - 30 * dt)
groundDrive(fVel, faceYaw + PI)
if stateTime > 1.05 then
fVel = 0
setState("Idle")
end
elseif state == "Swim" then
humanoid.WalkSpeed = 16
humanoid:Move(wantYaw and move or Vector3.zero, false)
humanoid.Jump = jumpHeld()
if wantYaw then
local d = angDiff(faceYaw, wantYaw)
faceYaw += math.clamp(d, -math.rad(360) * dt, math.rad(360) * dt)
moveYaw = faceYaw
play("swim", 1, 0.15)
else
play("swim_idle", 1, 0.2)
end
end
end
root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, faceYaw, 0)
local pitchT, rollT = 0, 0
if state == "Walk" then
local sf = math.clamp(fVel / CFG.RunMax, 0, 1)
pitchT = math.rad(CFG.TiltMaxForward) * (sf ^ 0.6)
local maxSide = math.rad(CFG.TiltMaxSide)
rollT = math.clamp(-turnRate * CFG.TiltSideGain, -maxSide, maxSide) * math.clamp(sf, 0.25, 1)
elseif state == "Skid" then
pitchT = -math.rad(18)
end
local a = 1 - math.exp(-10 * dt)
tiltPitch = lerp(tiltPitch, pitchT, a)
tiltRoll = lerp(tiltRoll, rollT, a)
if character:GetAttribute("M64ShiftLock") then
-- shift lock: Mario faces where the camera looks (you strafe with the stick)
if UIS.MouseEnabled then UIS.MouseBehavior = Enum.MouseBehavior.LockCenter end
if (state == "Idle" or state == "Walk" or state == "Crouch" or state == "Crawl" or state == "Jump" or state == "DoubleJump" or state == "Fall") and diveCancelT <= 0 then
local lv = flat(workspace.CurrentCamera.CFrame.LookVector)
if lv.Magnitude > 0.01 then faceYaw = yawOf(lv) end
end
end
local bp, fastA = 0, (diveCancelT > 0 and 5 or 12)
local cvy = root.AssemblyLinearVelocity.Y
local hsp = flat(root.AssemblyLinearVelocity).Magnitude
if state == "Dive" then
bp = math.clamp(math.atan2(-cvy, math.max(hsp, 8)), -math.rad(30), math.rad(75))
fastA = 18
elseif state == "Slide" then
bp = slideAng * 0.9
elseif state == "SlideKick" then
bp = -math.rad(14)
elseif AIR[state] and not NOPITCH[state] and cvy < -35 then
bp = math.rad(32) * math.clamp((-cvy - 35) / 60, 0, 1)
end
bodyPitch = lerp(bodyPitch, bp, 1 - math.exp(-fastA * dt))
baseC0[1] = bodyC0()
end
-- ================= FX: shadow, particles, wing cap, metal cap, footstep sounds =================
