end)
local groundColor = Color3.fromRGB(190, 190, 190)
local groundMat = Enum.Material.Plastic
local function hideShadow()
shadowImg.ImageTransparency = 1
end
local function updateShadow()
if not opts.shadow then hideShadow() return end
local origin = root.Position
local res = workspace:Raycast(origin, Vector3.new(0, -400, 0), shadowRay)
if not res then hideShadow() return end
local h = math.max(origin.Y - feetOffset() - res.Position.Y, 0)
local k = math.clamp(1 - h / 80, 0.35, 1)
local vis = math.clamp(1 - h / 200, 0.2, 1)
local d = CFG.ModelHeight * 0.85 * k
local n = res.Normal
local ref = math.abs(n.X) < 0.9 and Vector3.xAxis or Vector3.zAxis
local vx = (ref - n * ref:Dot(n)).Unit
shadow.Size = Vector3.new(d, 0.05, d)
shadow.CFrame = CFrame.fromMatrix(res.Position + n * 0.04, vx, n, vx:Cross(n))
shadowImg.ImageTransparency = 1 - 0.8 * vis
local inst = res.Instance
groundMat = res.Material
if inst and inst:IsA("BasePart") then
groundColor = inst.Color:Lerp(Color3.fromRGB(215, 215, 215), 0.55)
else
groundColor = Color3.fromRGB(190, 190, 190)
end
end

-- ---------- particles (real Parts, so they render on every device) ----------
local live = {}
local function spawnP(pos, vel, life, s0, s1, color, neon, grav, block)
if #live >= 140 then
local o = table.remove(live, 1)
pcall(function() o.p:Destroy() end)
end
local p = Instance.new("Part")
p.Name = "M64P"
p.Shape = block and Enum.PartType.Block or Enum.PartType.Ball
p.Material = neon and Enum.Material.Neon or Enum.Material.SmoothPlastic
p.Color = color
p.Anchored = true
p.CanCollide = false; p.CanQuery = false; p.CanTouch = false; p.CastShadow = false
p.Size = Vector3.one * math.max(s0, 0.05)
p.Transparency = neon and 0 or 0.3
p.CFrame = CFrame.new(pos)
p.Parent = fxFolder
live[#live + 1] = { p = p, pos = pos, vel = vel, t = 0, life = life, s0 = s0, s1 = s1, grav = grav, neon = neon,
ang = math.random() * 6, spin = block and (6 + math.random() * 6) or 0 }
end
local function updateParticles(dt)
for i = #live, 1, -1 do
local d = live[i]
d.t += dt
if d.t >= d.life or not d.p.Parent then
pcall(function() d.p:Destroy() end)
table.remove(live, i)
else
local a = d.t / d.life
d.vel = d.vel * math.max(0, 1 - 3 * dt) + Vector3.new(0, d.grav * dt, 0)
d.pos += d.vel * dt
d.ang += d.spin * dt
d.p.Size = Vector3.one * math.max(lerp(d.s0, d.s1, a), 0.03)
d.p.Transparency = d.neon and (a * a) or lerp(0.3, 1, a)
d.p.CFrame = CFrame.new(d.pos) * CFrame.Angles(d.ang, d.ang * 0.7, d.ang * 1.3)
end
end
end
local function puff(pos, n, speed, size)
if not opts.particles then return end
local s = size * U()
local col = groundColor:Lerp(Color3.new(1, 1, 1), 0.45)
for _ = 1, n do
local a = math.random() * math.pi * 2
local sp = speed * (0.4 + math.random() * 0.6)
spawnP(pos + Vector3.new(0, 0.15 * U(), 0),
Vector3.new(math.cos(a) * sp, sp * (0.3 + math.random() * 0.5), math.sin(a) * sp),
0.4 + math.random() * 0.3, s * 0.3, s * 1.0, col, false, 3, false)
end
end
local function ring(pos, n, speed, size)
if not opts.particles then return end
local s = size * U()
local col = groundColor:Lerp(Color3.new(1, 1, 1), 0.45)
for i = 1, n do
local a = (i / n) * math.pi * 2
local dir = Vector3.new(math.cos(a), 0, math.sin(a))
spawnP(pos + dir * 0.8 * U(), dir * speed + Vector3.new(0, 1, 0), 0.5 + math.random() * 0.2,
s * 0.35, s * 1.0, col, false, 1, false)
end
end
local function stars(pos, n, speed, size)
if not opts.particles then return end
local s = (size or 0.9) * U() * 0.45
local col = FXS.metal and Color3.fromRGB(235, 240, 255) or Color3.fromRGB(255, 230, 90)
for _ = 1, n do
local v = Vector3.new(math.random() - 0.5, math.random() * 0.8 + 0.2, math.random() - 0.5).Unit * (speed or 6) * (0.5 + math.random() * 0.5)
spawnP(pos, v, 0.45 + math.random() * 0.4, s, 0.05, col, true, -6, true)
end
end

