local hbH = 160
local function updateHitbox()
local u = CFG.ModelHeight / 160
local want = SHORT_HB[state] and 100 or 160
hbH = hbH + (want - hbH) * 0.3
HB.h = want
local r, H = 37 * u, hbH * u
hbPart.Size = Vector3.new(H, r * 2, r * 2)
hbWeld.C0 = CFrame.new(0, H / 2 - rigFeet() + HB_LIFT, 0) * CFrame.Angles(0, 0, math.pi / 2)
