hbPart.Color = SHORT_HB[state] and Color3.fromRGB(255, 200, 60) or Color3.fromRGB(255, 60, 60)
hbGui.Enabled = opts.hitbox and true or false
hbGui.StudsOffsetWorldSpace = Vector3.new(0, H / 2 + 1.2, 0)
hbLbl.Text = string.format("%s  |  H %d  R 37", tostring(state), want)
local on = opts.hitbox and os.clock() < atkUntil
if on then
local rule = ATTACK[atkKind] or { 40, 90 }
local reach = (37 + rule[1]) * u
atkPart.Size = Vector3.new(H, reach * 2, reach * 2)
atkWeld.C0 = CFrame.new(0, H / 2 - rigFeet(), 0) * CFrame.Angles(0, 0, math.pi / 2)
atkPart.Transparency = 0.75
else
atkPart.Transparency = 1
end
