punch = { "rbxasset://sounds/swordslash.wav", 1.8 }, kick = { "rbxasset://sounds/swordslash.wav", 1.4 },
dive = { "rbxasset://sounds/swordslash.wav", 1.0 }, pound = { "rbxasset://sounds/action_jump_land.mp3", 0.6 },
land = { "rbxasset://sounds/action_jump_land.mp3", 1.2 }, hurt = { "rbxasset://sounds/uuhhh.mp3", 1.4 },
