}
local sfxCache = {}
local function resolveSfx(name)
if sfxCache[name] ~= nil then return sfxCache[name] end
local v = SOUNDS[name]
local id = nil
if type(v) == "string" and v ~= "" then
if v:match("^https?://") then
local ok, res = pcall(function()
if isfile and writefile and getcustomasset then
local fname = "m64_" .. name .. ".snd"
if not isfile(fname) then writefile(fname, game:HttpGet(v)) end
return getcustomasset(fname)
end
end)
if ok and res then id = res end
else
id = v
end
end
sfxCache[name] = id or false
return id or false
end
task.spawn(function()
for name in pairs(FALL) do pcall(resolveSfx, name) end
end)
