-- ---------- wing cap (procedural wings on the head) ----------
local wings = {}
local wingsBuilt = false
local WING_COLOR = Color3.fromRGB(252, 252, 255)
local WING_TIP = Color3.fromRGB(225, 228, 240)
local function buildWings()
if wingsBuilt then return end
wingsBuilt = true
local head = piece["Head"]
local hs = head.Size
local hz = hs.Z
-- {length, width, sweep angle in degrees} - five overlapping rounded feathers per wing
local FEATHER = { { 1.00, 0.30, 0 }, { 1.05, 0.30, 17 }, { 0.98, 0.28, 35 }, { 0.84, 0.26, 54 }, { 0.64, 0.24, 76 } }
for _, side in ipairs({ -1, 1 }) do
local pivot = Instance.new("Part")
pivot.Name = "FXPivot"
pivot.Size = Vector3.new(0.2, 0.2, 0.2)
pivot.Transparency = 1
pivot.CanCollide = false; pivot.CanQuery = false; pivot.CanTouch = false; pivot.Massless = true; pivot.CastShadow = false
pivot.Parent = marioModel
local pw = Instance.new("Weld")
pw.Part0 = head; pw.Part1 = pivot
pw.C0 = CFrame.new(hs.X * 0.28, hs.Y * 0.05, side * hs.Z * 0.5)
pw.Parent = pivot
local w = { side = side, pivot = pivot, weld = pw, feathers = {} }
for i, fe in ipairs(FEATHER) do
local len = hz * 0.95 * fe[1]
local width = hz * fe[2]
local phi = math.rad(fe[3])
local f = Instance.new("Part")
f.Name = "FXWing"
f:SetAttribute("FXWing", true)
f.Size = Vector3.new(hz * 0.09, width, len)
f.Color = Color3.fromRGB(255, 255, 255):Lerp(Color3.fromRGB(200, 208, 235), (i - 1) / (#FEATHER - 1))
f.Material = Enum.Material.SmoothPlastic
f.Transparency = 1
f.CanCollide = false; f.CanQuery = false; f.CanTouch = false; f.Massless = true; f.CastShadow = false
local sm = Instance.new("SpecialMesh")
sm.MeshType = Enum.MeshType.Sphere
sm.Parent = f
f.Parent = marioModel
local d = Vector3.new(0, math.sin(phi), side * math.cos(phi))
local fw = Instance.new("Weld")
fw.Part0 = pivot; fw.Part1 = f
fw.C0 = CFrame.new(d * (len / 2 + hz * 0.03)) * CFrame.Angles(-side * phi, 0, 0)
fw.Parent = f
w.feathers[i] = f
end
wings[#wings + 1] = w
end
end
local wingPhase, wingAmp, wingFreq = 0, 0.1, 2.2
local function updateWings(dt, grounded)
if not wingsBuilt then return end
local show = FXS.wing
local hs = piece["Head"].Size
local freq, amp, base
if FXS.gliding then freq, amp, base = 16, 0.55, 0.35
elseif not grounded then freq, amp, base = 8, 0.32, 0.4
else freq, amp, base = 2.4, 0.1, 0.5 end
local a = 1 - math.exp(-8 * dt)
wingAmp = lerp(wingAmp, amp, a)
wingFreq = lerp(wingFreq, freq, a)
wingPhase += dt * wingFreq
local theta = base + math.sin(wingPhase) * wingAmp
for _, w in ipairs(wings) do
w.weld.C0 = CFrame.new(hs.X * 0.28, hs.Y * 0.05, w.side * hs.Z * 0.5) * CFrame.Angles(0, w.side * theta, 0)
for _, f in ipairs(w.feathers) do
f.Transparency = show and 0 or 1
end
end
end
local function setWing(on, silent)
FXS.wing = on and true or false
if not silent then sfx("cap") end
player:SetAttribute("M64Wing", FXS.wing)
if FXS.wing then
buildWings()
stars(root.Position + Vector3.new(0, CFG.ModelHeight * 0.4, 0), 10, 8, 1)
else
FXS.gliding = false
end
end

-- ---------- metal cap ----------
local METAL_COLOR = Color3.fromRGB(190, 196, 210)
local metalTex = nil
local origLook = {}
local function applyMetal(on)
if on and metalTex == nil then
metalTex = false
if CFG.TextureId == "" and textureContent then
local ok, res = pcall(buildTexture, true)
if ok and res then metalTex = res end
end
end
for _, d in ipairs(marioModel:GetDescendants()) do
if d:IsA("BasePart") and not d:GetAttribute("FXWing") and d.Name ~= "FXPivot" and d.Name ~= "M64Hitbox" then
if on then
if not origLook[d] then
local o = { Color = d.Color, Material = d.Material, Reflectance = d.Reflectance }
if d:IsA("MeshPart") then
o.TextureID = d.TextureID
pcall(function() o.TextureContent = d.TextureContent end)
end
origLook[d] = o
end
if d:IsA("MeshPart") then
if metalTex then
-- same SM64 shading, but chrome-grey (keeps his face, cap and overalls readable)
pcall(function() d.TextureContent = metalTex end)
d.Color = Color3.new(1, 1, 1)
else
pcall(function() d.TextureID = "" end)
pcall(function() d.TextureContent = Content.none end)
d.Color = METAL_COLOR
end
else
d.Color = METAL_COLOR
end
d.Material = Enum.Material.Metal
d.Reflectance = 0.4
else
local o = origLook[d]
if o then
d.Color = o.Color
d.Material = o.Material
d.Reflectance = o.Reflectance
if d:IsA("MeshPart") then
pcall(function() d.TextureID = o.TextureID or "" end)
if o.TextureContent then pcall(function() d.TextureContent = o.TextureContent end) end
end
origLook[d] = nil
end
end
end
end
end
local function setMetal(on, silent)
FXS.metal = on and true or false
if not silent then sfx("cap") end
player:SetAttribute("M64Metal", FXS.metal)
applyMetal(FXS.metal)
stars(root.Position + Vector3.new(0, CFG.ModelHeight * 0.4, 0), 10, 8, 1)
end

-- ---------- SM64 light (ported from sm64_v19) ----------
local Lighting_ = game:GetService("Lighting")
local LS = shared.M64Light
if not LS then
LS = { on = false, saved = nil, fx = {}, sunSaved = {}, sunDummy = nil, cc = nil, solveClock = nil, solveLat = nil, check = 0 }
shared.M64Light = LS
end
local LIGHT = {
Ambient = Color3.fromRGB(127, 127, 127),
OutdoorAmbient = Color3.fromRGB(127, 127, 127),
Brightness = 2,
ColorShift_Top = Color3.new(0, 0, 0),
ColorShift_Bottom = Color3.new(0, 0, 0),
GlobalShadows = false,
EnvironmentDiffuseScale = 0,
EnvironmentSpecularScale = 0,
ExposureCompensation = 0,
}
local function setLightProp(k, v)
pcall(function() if Lighting_[k] ~= v then Lighting_[k] = v end end)
end
local function applyLightProps()
for k, v in pairs(LIGHT) do setLightProp(k, v) end
end
local function hideSun()
local hasSky = false
for _, o in ipairs(Lighting_:GetChildren()) do
if o:IsA("Sky") and o ~= LS.sunDummy then
hasSky = true
if LS.sunSaved[o] == nil then LS.sunSaved[o] = { o.SunAngularSize, o.MoonAngularSize } end
if o.SunAngularSize ~= 0 then o.SunAngularSize = 0 end
if o.MoonAngularSize ~= 0 then o.MoonAngularSize = 0 end
end
end
if not hasSky and not LS.sunDummy then
