pcall(hideSun)
end))
local LIGHT_RIGHT, LIGHT_UP, LIGHT_BACK = 0.5, 0.75, 0.5
local lastLightFwd = Vector3.new(0, 0, -1)
local function lightTarget()
if not opts.lightFollow then return Vector3.new(LIGHT_RIGHT, LIGHT_UP, LIGHT_BACK).Unit end
local cam = workspace.CurrentCamera
if not cam then return nil end
local look = cam.CFrame.LookVector
local f = Vector3.new(look.X, 0, look.Z)
if f.Magnitude < 0.05 then f = lastLightFwd end
f = f.Unit
lastLightFwd = f
local r = f:Cross(Vector3.new(0, 1, 0))
return (r * LIGHT_RIGHT + Vector3.new(0, LIGHT_UP, 0) - f * LIGHT_BACK).Unit
end
local function setSun(c, l)
Lighting_.ClockTime = c % 24
Lighting_.GeographicLatitude = math.clamp(l, -90, 90)
end
local function followCamera()
local target = lightTarget()
if not target then return end
if not LS.solveClock then LS.solveClock, LS.solveLat = Lighting_.ClockTime, Lighting_.GeographicLatitude end
for _ = 1, 4 do
setSun(LS.solveClock, LS.solveLat)
local d0 = Lighting_:GetSunDirection()
local err = target - d0
if err.Magnitude < 0.004 then break end
setSun(LS.solveClock + 0.1, LS.solveLat)
local dc = (Lighting_:GetSunDirection() - d0) / 0.1
setSun(LS.solveClock, LS.solveLat + 1)
local dl = Lighting_:GetSunDirection() - d0
local a11, a12, a22 = dc:Dot(dc) + 1e-6, dc:Dot(dl), dl:Dot(dl) + 1e-6
local det = a11 * a22 - a12 * a12
if math.abs(det) < 1e-12 then break end
local b1, b2 = dc:Dot(err), dl:Dot(err)
local x1 = (b1 * a22 - b2 * a12) / det
local x2 = (a11 * b2 - a12 * b1) / det
LS.solveClock = LS.solveClock + math.clamp(x1, -3, 3)
LS.solveLat = math.clamp(LS.solveLat + math.clamp(x2, -25, 25), -90, 90)
end
setSun(LS.solveClock, LS.solveLat)
end
fxTrack(RunService.RenderStepped:Connect(function()
if LS.on and LS.saved then pcall(followCamera) end
end))
if LS.on then task.defer(applyLight) end

