-- ---------- per-frame driver ----------
local prevGround, lastAirState, minVy = true, "Idle", 0
local runT, skidT, sparkT, stepT = 0, 0, 0, 0.08
local failures = 0
local lastSfxState = state
local function driver(dt)
if humanoid.Health <= 0 then hideShadow() return end
if state ~= lastSfxState then
lastSfxState = state
local sn = STATE_SFX[state]
if sn then sfx(sn) end
end
local grounded = humanoid.FloorMaterial ~= Enum.Material.Air
local vel = root.AssemblyLinearVelocity
local hsp = flat(vel).Magnitude
local feet = root.Position - Vector3.new(0, feetOffset(), 0)
if not grounded then
lastAirState = state
if vel.Y < minVy then minVy = vel.Y end
else
FXS.wasGliding = false
end
if grounded and not prevGround then
local fall = -minVy
minVy = 0
if lastAirState == "GroundPound" then
ring(feet + Vector3.new(0, 0.2, 0), 16, 20, 2.2)
puff(feet, 10, 10, 2)
stars(feet + Vector3.new(0, 0.5, 0), 8, 14, 1)
if opts.sound then local t = THUD:Clone(); t.Parent = root; t:Play(); Debris:AddItem(t, 3) end
elseif fall > 14 then
puff(feet, math.clamp(math.floor(fall / 5), 3, 12), 7, 1.5)
playStep(stepSound(), 80, 92, math.clamp(0.7 + fall / 90, 0.7, 1.5))
else
puff(feet, 2, 4, 1)
end
elseif prevGround and not grounded and vel.Y > 12 then
puff(feet, 4, 5, 1.2)
end
prevGround = grounded
if grounded then
if state == "Walk" and hsp > CFG.RunAnimAbove then
runT -= dt
if runT <= 0 then
runT = 0.09
puff(feet - dirOf(faceYaw) * 0.6 * U(), 1, 3, 1.1)
end
else
runT = 0
end
if state == "Skid" or state == "SlideKick" or state == "DiveSlide" or state == "Slide" then
skidT -= dt
if skidT <= 0 and hsp > 4 then
skidT = 0.05
puff(feet, 2, 5, 1.3)
end
end
if (state == "Walk" or state == "Crawl") and hsp > 1 then
stepT -= dt
if stepT <= 0 then
local crawl = state == "Crawl"
stepT = crawl and 0.5 or math.clamp(0.35 * (16 / hsp), 0.18, 0.4)
playStep(stepSound(), 86, 100, crawl and 0.4 or 1)
end
else
stepT = 0.08
end
end
if state == "TripleJump" or FXS.gliding then
sparkT -= dt
if sparkT <= 0 then
sparkT = 0.07
stars(root.Position - Vector3.new(0, CFG.ModelHeight * 0.2, 0), 1, 3, 0.8)
end
end
end
