-- animated eyes: double blink, closed when sleeping / bonked, X eyes when dead, extra Pursuitcore faces
task.spawn(function()
local E = CFG.Eyes
if not E or not CFG.TexImg then return end
local B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lut = {}
for i = 1, 64 do lut[B:sub(i, i)] = i - 1 end
local function decode(palStr, rle)
local pal = {}
for i = 0, #palStr / 6 - 1 do
local h = palStr:sub(i * 6 + 1, i * 6 + 6)
pal[i] = { tonumber(h:sub(1, 2), 16), tonumber(h:sub(3, 4), 16), tonumber(h:sub(5, 6), 16) }
end
local buf = buffer.create(E.w * E.h * 4)
local p = 0
for i = 1, #rle, 3 do
local c = pal[lut[rle:sub(i, i)]]
local len = lut[rle:sub(i + 1, i + 1)] * 64 + lut[rle:sub(i + 2, i + 2)] + 1
for _ = 1, len do
buffer.writeu8(buf, p, c[1]); buffer.writeu8(buf, p + 1, c[2]); buffer.writeu8(buf, p + 2, c[3]); buffer.writeu8(buf, p + 3, 255)
p += 4
end
end
return buf
end
local bufs = {}
local baseN = #E.rle
for n, rle in ipairs(E.rle) do bufs[n] = decode(E.pal, rle) end
for n, rle in ipairs(EYES_EXTRA.rle) do
local ok, b = pcall(decode, EYES_EXTRA.pal, rle)
if ok then bufs[baseN + n] = b end
end
