else
if st == "Bonk" or st == "AirBonk" or st == "Hurt" or curName == "sleep_idle" or curName == "ground_pound_landing" then
want = 3
elseif PC.Enabled and PC.AutoFaces and (string.find(st, "Punch") or string.find(st, "Kick") or string.find(st, "Dive") or string.find(st, "GP") or string.find(st, "Pound") or string.find(st, "Slide")) then
