-- ---------- Pursuitcore: a swapped character copies the game's own actions as Mario animations ----------
if PK.puppet then
local seen = shared.PursuitSeenAnims
local acts, known, punchIdx = {}, setmetatable({}, { __mode = "k" }), 0
local animObj = humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 5)
local function classify(track)
local n = string.lower(track.Name)
local id = ""
pcall(function()
n = n .. " " .. string.lower(track.Animation.Name)
id = tostring(track.Animation.AnimationId)
end)
n = string.gsub(n, "[%s_%-%.]", "")
if not seen.names[n] then
seen.names[n] = true
table.insert(seen.list, n .. "   " .. id)
end
for _, rule in ipairs(PC.Actions) do
for _, w in ipairs(rule[1]) do
if string.find(n, w, 1, true) then return rule end
end
end
for _, w in ipairs(PC.LocoWords) do
if string.find(n, w, 1, true) then return nil end
end
if PC.UnknownAction and not track.Looped and track.Priority ~= Enum.AnimationPriority.Idle and track.Priority ~= Enum.AnimationPriority.Movement then
return { {}, PC.UnknownAction, 5 }
end
return nil
end
local wasAir, landHold, lastFace = false, 0, nil
local conn
conn = RunService.Heartbeat:Connect(function(dt)
if PK.killed or not character.Parent then conn:Disconnect() return end
if dead or humanoid.Health <= 0 then return end
if animObj then
for _, t in ipairs(animObj:GetPlayingAnimationTracks()) do
if not known[t] then
known[t] = true
local ok, rule = pcall(classify, t)
if ok and rule then
local anim = rule[2]
if type(anim) == "table" then
punchIdx = punchIdx % #anim + 1
anim = anim[punchIdx]
end
table.insert(acts, { track = t, anim = anim, face = rule[3], fresh = true })
end
end
end
end
local a
for i = #acts, 1, -1 do
local x = acts[i]
if x.track.IsPlaying then a = x break end
table.remove(acts, i)
end
local face = nil
if a then
if a.fresh then
a.fresh = false
if curName == a.anim then curName = nil end
local sp = 1
local len = trackLength(a.anim, nil)
if len and not LOOPED[a.anim] and a.track.Length > 0.05 then sp = math.clamp(len / a.track.Length, 0.4, 3) end
a.speed = sp
end
play(a.anim, a.speed or 1, 0.05)
face = a.face
else
local stt = humanoid:GetState()
local v = root.AssemblyLinearVelocity
local hs = flat(v).Magnitude
local air = stt == Enum.HumanoidStateType.Freefall or stt == Enum.HumanoidStateType.Jumping
if stt == Enum.HumanoidStateType.Swimming then
play(hs > 2 and "swim" or "swim_idle", 1, 0.1)
elseif stt == Enum.HumanoidStateType.Climbing then
play("ledge_idle", 1, 0.1)
elseif stt == Enum.HumanoidStateType.FallingDown or stt == Enum.HumanoidStateType.Ragdoll or stt == Enum.HumanoidStateType.PlatformStand then
play("hurt_front", 1, 0.1)
face = 3
elseif air then
wasAir = true
if v.Y > 3 then play("single_jump", 1, 0.05) else play("general_fall", 1, 0.1) end
else
if wasAir then
wasAir = false
landHold = 0.18
curName = nil
play("general_land", 1, 0.04)
end
if landHold > 0 then
landHold -= dt
elseif hs < 1 then
play("idle", 1, 0.15)
elseif hs < 7 then
play("slow_walk", sm64Rate(hs), 0.1)
elseif hs < 17 then
play("walking", sm64Rate(hs), 0.1)
else
play("running", sm64Rate(hs), 0.1)
if hs > PC.ChaseSpeed and PC.AutoFaces then face = 5 end
end
end
end
if PC.FaceLock == nil and face ~= lastFace then
lastFace = face
pcall(function() character:SetAttribute("M64Face", face) end)
end
end)
end
end
