local function lowerS(s) return string.lower(tostring(s)) end
local function normS(s) return (string.gsub(lowerS(s), "[%s_%-%.]", "")) end
local function hasAny(s, list)
for _, w in ipairs(list) do
if string.find(s, w, 1, true) then return true end
end
return false
end

-- ---- lobby or match? returns true (match), false (lobby) or nil (cannot tell) ----
local BOOL_NAMES = { "InGame", "InRound", "InMatch", "Playing", "IsPlaying", "InGameplay", "IsInGame", "InLobby", "IsInLobby" }
local STR_NAMES = { "State", "Status", "Location", "Zone", "Area", "Stage", "Phase", "GameState", "Mode" }
local lobbyObj, lobbyAt, lobbyDeep = nil, -100, false
local lobbyCF, lobbySize = nil, nil
local function boundsOf(o)
if o:IsA("Model") then return o:GetBoundingBox() end
if o:IsA("BasePart") then return o.CFrame, o.Size end
local mn, mx
for _, d in ipairs(o:GetDescendants()) do
if d:IsA("BasePart") then
local p, s = d.Position, d.Size / 2
local lo, hi = p - s, p + s
mn = mn and Vector3.new(math.min(mn.X, lo.X), math.min(mn.Y, lo.Y), math.min(mn.Z, lo.Z)) or lo
mx = mx and Vector3.new(math.max(mx.X, hi.X), math.max(mx.Y, hi.Y), math.max(mx.Z, hi.Z)) or hi
end
end
if not mn then return nil end
return CFrame.new((mn + mx) / 2), mx - mn
end
local function findLobby()
if os.clock() - lobbyAt < 5 then return lobbyObj end
lobbyAt = os.clock()
lobbyObj, lobbyCF, lobbySize = nil, nil, nil
for _, n in ipairs(PC.LobbyModelNames) do
local o = workspace:FindFirstChild(n)
if not o and not lobbyDeep then o = workspace:FindFirstChild(n, true) end
if o then lobbyObj = o break end
end
lobbyDeep = true
if lobbyObj then
local ok, cf, sz = pcall(boundsOf, lobbyObj)
if ok and cf then lobbyCF, lobbySize = cf, sz else lobbyObj = nil end
end
return lobbyObj
end
local function detectGame()
if PC.Mode == "game" then return true end
if PC.Mode == "lobby" then return false end
if PC.IsInGame then
local ok, r = pcall(PC.IsInGame, lp)
if ok and r ~= nil then return r end
end
for _, h in ipairs({ lp, lp.Character }) do
for _, n in ipairs(BOOL_NAMES) do
local v = h:GetAttribute(n)
if type(v) == "boolean" then
if string.find(lowerS(n), "lobby", 1, true) then return not v end
return v
end
end
for _, n in ipairs(STR_NAMES) do
local v = h:GetAttribute(n)
if type(v) == "string" then
local s = lowerS(v)
if hasAny(s, PC.LobbyWords) then return false end
if hasAny(s, PC.GameWords) then return true end
end
end
end
if lp.Team then
local s = lowerS(lp.Team.Name)
if hasAny(s, PC.LobbyWords) then return false end
if hasAny(s, PC.GameWords) then return true end
end
local char = lp.Character
local rp = char and char:FindFirstChild("HumanoidRootPart")
if rp and findLobby() and lobbyCF then
local rel = lobbyCF:PointToObjectSpace(rp.Position)
local pad = 30
local inside = math.abs(rel.X) <= lobbySize.X / 2 + pad and math.abs(rel.Y) <= lobbySize.Y / 2 + 60 and math.abs(rel.Z) <= lobbySize.Z / 2 + pad
return not inside
end
return nil
end

-- ---- which other characters are Dante / Party Pony ----
local function textOf(m)
local t = {}
local plr = Players_:GetPlayerFromCharacter(m)
if not plr then t[#t + 1] = normS(m.Name) end
local function addFrom(o)
for _, v in pairs(o:GetAttributes()) do
if type(v) == "string" then t[#t + 1] = normS(v) end
end
for _, c in ipairs(o:GetChildren()) do
if c:IsA("StringValue") then t[#t + 1] = normS(c.Value) end
end
end
addFrom(m)
if plr then addFrom(plr) end
if m.Parent and m.Parent ~= workspace then t[#t + 1] = normS(m.Parent.Name) end
return table.concat(t, "|")
end
local function swapMatch(m)
local s = textOf(m)
if PC.SwapDante and string.find(s, "dante", 1, true) then return true end
if PC.SwapPartyPony and (string.find(s, "partypony", 1, true) or string.find(s, "pony", 1, true)) then return true end
if PC.SwapTerminators and (string.find(s, "terminator", 1, true) or string.find(s, "killer", 1, true)) then return true end
if PC.CustomMatch then
local ok, r = pcall(PC.CustomMatch, m)
if ok and r then return true end
end
return false
end

