-- ---- Mario icon for the Dante / Party Pony menu pictures ----
local iconContent, iconImg, iconErr, iconTry = nil, nil, nil, -100
local function buildIcon()
if iconContent then return iconContent end
if iconContent == false and os.clock() - iconTry < 10 then return false end
iconTry = os.clock()
iconContent = false
local ok, err = pcall(function()
local B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lut = {}
for i = 1, 64 do lut[B:sub(i, i)] = i - 1 end
local pal = {}
for i = 0, #MARIO_ICON.pal / 6 - 1 do
local h = MARIO_ICON.pal:sub(i * 6 + 1, i * 6 + 6)
pal[i] = { tonumber(h:sub(1, 2), 16), tonumber(h:sub(3, 4), 16), tonumber(h:sub(5, 6), 16) }
end
local n = MARIO_ICON.n
local buf = buffer.create(n * n * 4)
local p = 0
local rle = MARIO_ICON.rle
for i = 1, #rle, 3 do
local c = pal[lut[rle:sub(i, i)]]
local len = lut[rle:sub(i + 1, i + 1)] * 64 + lut[rle:sub(i + 2, i + 2)] + 1
for _ = 1, len do
buffer.writeu8(buf, p, c[1]); buffer.writeu8(buf, p + 1, c[2]); buffer.writeu8(buf, p + 2, c[3]); buffer.writeu8(buf, p + 3, 255)
p += 4
end
end
local img = game:GetService("AssetService"):CreateEditableImage({ Size = Vector2.new(n, n) })
img:WritePixelsBuffer(Vector2.zero, Vector2.new(n, n), buf)
iconImg = img -- keep a reference so it is never collected
iconContent = Content.fromObject(img)
end)
if not ok then iconErr = tostring(err) end
return iconContent
end

local iconOrig = setmetatable({}, { __mode = "k" }) -- image -> { img, ro, rs, sc, col, ok }
local iconSweepAt = -100
local iconCount = 0
local SKIP_GUI = { PursuitCoreUI = true, MarioFX = true, MarioControls = true, MarioToggles = true, MarioDebug = true, MarioError = true }
local function isImg(o) return o:IsA("ImageLabel") or o:IsA("ImageButton") end
local function wantName(s)
if #s == 0 then return false end
if PC.SwapDante and string.find(s, "dante", 1, true) then return true end
if PC.SwapPartyPony and (string.find(s, "partypony", 1, true) or string.find(s, "pony", 1, true)) then return true end
return false
end
-- the biggest picture inside o (o itself counts)
local function bigImage(o)
local best, area = nil, 0
local function consider(x)
if isImg(x) then
local sz = x.AbsoluteSize
if sz.X >= 24 and sz.Y >= 24 and sz.X * sz.Y > area then best, area = x, sz.X * sz.Y end
end
end
consider(o)
for _, x in ipairs(o:GetDescendants()) do consider(x) end
return best
end
local function revertIcon(d, rec)
pcall(function()
d.ImageContent = Content.none
d.Image = rec.img
d.ImageRectOffset = rec.ro
d.ImageRectSize = rec.rs
d.ScaleType = rec.sc
d.ImageColor3 = rec.col
end)
iconOrig[d] = nil
end
local function applyIcon(d, ic)
local rec = iconOrig[d]
if not rec then
rec = { img = d.Image, ro = d.ImageRectOffset, rs = d.ImageRectSize, sc = d.ScaleType, col = d.ImageColor3 }
iconOrig[d] = rec
else
-- the game put its own picture back: remember it and swap again
local still = false
pcall(function() still = d.ImageContent.SourceType == Enum.ContentSourceType.Object end)
if still and d.Image == "" then return end
if d.Image ~= "" then rec.img = d.Image end
end
pcall(function()
d.ImageRectOffset = Vector2.zero
d.ImageRectSize = Vector2.zero
d.ScaleType = Enum.ScaleType.Crop
d.ImageColor3 = Color3.new(1, 1, 1)
d.ImageContent = ic
end)
local good = false
pcall(function() good = d.ImageContent.SourceType == Enum.ContentSourceType.Object end)
rec.ok = good
end
local function iconKey(d)
local rec = iconOrig[d]
local img = rec and rec.img or d.Image
local ro = rec and rec.ro or d.ImageRectOffset
local rs = rec and rec.rs or d.ImageRectSize
return tostring(img) .. "|" .. tostring(ro) .. "|" .. tostring(rs)
end
local function iconStatus()
if iconContent == false and iconErr then return "can't build icon: turn on Allow Mesh / Image APIs" end
return iconCount .. " swapped"
end
local function iconSweep()
if os.clock() - iconSweepAt < 1.2 then return end
iconSweepAt = os.clock()
local pg = lp:FindFirstChild("PlayerGui")
if not pg then return end
local on = PC.Enabled and PC.SwapIcons and (PC.SwapDante or PC.SwapPartyPony)
if not on then
for d, rec in pairs(iconOrig) do revertIcon(d, rec) end
iconCount = 0
return
end
local ic = buildIcon()
if not ic then iconCount = 0 return end
local all = pg:GetDescendants()
local targets = {}
local function skip(d)
local o = d
while o and o ~= pg do
if SKIP_GUI[o.Name] and o.Parent == pg then return true end
o = o.Parent
end
return false
end
-- 1) a name or text that says Dante / Party Pony: take the biggest picture of that card
for _, d in ipairs(all) do
if d:IsA("GuiObject") and not skip(d) then
local hit = false
if d:IsA("TextLabel") or d:IsA("TextButton") then
local t = normS(d.Text)
hit = #t <= 30 and wantName(t)
end
if not hit then hit = wantName(normS(d.Name)) end
if hit then
local o = d
for _ = 1, 5 do
local pic = bigImage(o)
if pic then targets[pic] = true break end
o = o.Parent
if not o or o == pg then break end
end
end
end
end
-- 2) the same picture used anywhere else (equipped icon, loadout slots) is swapped too
local keys = {}
for d in pairs(targets) do keys[iconKey(d)] = true end
for d, rec in pairs(iconOrig) do
if d.Parent then keys[iconKey(d)] = true end
end
local extra, nExtra = {}, 0
for _, d in ipairs(all) do
if isImg(d) and not targets[d] and not skip(d) and d.AbsoluteSize.X >= 24 then
local k = iconKey(d)
if keys[k] and not string.find(k, "^|") then extra[d] = true; nExtra += 1 end
end
end
-- a picture shared by many things is a background, not a character icon: leave those alone
if nExtra <= 8 then
for d in pairs(extra) do targets[d] = true end
end
for d in pairs(targets) do
if d.Parent then applyIcon(d, ic) end
end
local n = 0
for d, rec in pairs(iconOrig) do
if d.Parent and rec.ok then n += 1 end
end
iconCount = n
end

-- ---- Pursuitcore music: replaces the game music with the LMS / chase tracks ----
local SoundService_ = game:GetService("SoundService")
local MUS = { sounds = {}, failAt = {}, err = {}, cur = nil, last = nil, peak = 0, chaseUntil = 0,
muted = {}, hooks = {}, seen = {}, seenList = {}, hintLMS = false, hintChase = false, status = "off" }
for _, o in ipairs(SoundService_:GetChildren()) do
if string.sub(o.Name, 1, 17) == "PursuitMarioMusic" then pcall(function() o:Destroy() end) end
end
local MUSIC_WORDS = { "music", "theme", "bgm", "ost", "song", "soundtrack", "lms", "chase", "laststand", "intense" }
local LMS_WORDS = { "lms", "laststand", "lastman", "lastperson", "lastsurvivor", "lastuser" }
local CHASE_WORDS = { "chase", "chasing", "hunted", "terminatortheme", "killertheme" }
local gameSounds = setmetatable({}, { __mode = "k" })
local function addSound(d) if d:IsA("Sound") then gameSounds[d] = true end end
for _, root in ipairs({ SoundService_, workspace }) do
for _, d in ipairs(root:GetDescendants()) do addSound(d) end
root.DescendantAdded:Connect(addSound)
end
task.spawn(function()
local pg = lp:WaitForChild("PlayerGui", 30)
if pg then
for _, d in ipairs(pg:GetDescendants()) do addSound(d) end
pg.DescendantAdded:Connect(addSound)
end
end)
local function isMusicSound(snd)
if not snd.Parent or string.sub(snd.Name, 1, 17) == "PursuitMarioMusic" then return false end
local ch = lp.Character
if ch and snd:IsDescendantOf(ch) then return false end
local p = snd.Parent
if p:IsA("BasePart") or p:IsA("Attachment") then return false end
local nm = normS(snd.Name)
if hasAny(nm, MUSIC_WORDS) then return true end
return snd.Looped and snd.TimeLength >= 30 and (p == SoundService_ or p == workspace or p:IsA("Folder"))
end
local function scanGameMusic()
local hl, hc = false, false
for snd in pairs(gameSounds) do
if not snd.Parent then
gameSounds[snd] = nil
elseif snd.IsPlaying and isMusicSound(snd) then
local nm = normS(snd.Name)
if hasAny(nm, LMS_WORDS) then hl = true elseif hasAny(nm, CHASE_WORDS) then hc = true end
local key = nm .. "  " .. tostring(snd.SoundId)
if not MUS.seen[key] then
MUS.seen[key] = true
table.insert(MUS.seenList, snd.Name .. "   " .. tostring(snd.SoundId))
end
end
end
MUS.hintLMS, MUS.hintChase = hl, hc
end
local function muteGame(on)
if on then
for snd in pairs(gameSounds) do
if snd.Parent and MUS.muted[snd] == nil and snd.IsPlaying and isMusicSound(snd) then
MUS.muted[snd] = snd.Volume
MUS.hooks[snd] = snd:GetPropertyChangedSignal("Volume"):Connect(function()
if MUS.muted[snd] ~= nil and snd.Volume > 0 then
MUS.muted[snd] = snd.Volume
snd.Volume = 0
end
end)
snd.Volume = 0
end
end
else
for snd, v in pairs(MUS.muted) do
if MUS.hooks[snd] then MUS.hooks[snd]:Disconnect() end
pcall(function() if snd.Parent then snd.Volume = v end end)
end
MUS.muted, MUS.hooks = {}, {}
end
end
local function resolveAudio(v)
if type(v) == "number" then return "rbxassetid://" .. v end
if type(v) ~= "string" or v == "" then return nil end
if string.find(v, "^rbxassetid://") or string.find(v, "^rbxasset://") then return v end
if string.find(v, "^%d+$") then return "rbxassetid://" .. v end
if not getcustomasset then return nil end
if string.find(v, "^https?://") then
local fname = "pc_music_" .. string.sub(string.gsub(v, "[^%w]", ""), -40) .. ".mp3"
if not (isfile and isfile(fname)) then
if not (writefile and game.HttpGet) then return nil end
writefile(fname, game:HttpGet(v))
end
return getcustomasset(fname)
end
if isfile and isfile(v) then return getcustomasset(v) end
return nil
end
local MUS_FILES = {
lms = { "MusicLMS", "pc_lms.mp3", "lms.mp3", "Powerful_Mario__Super_Mario_64__-_FL_Studio_Arrangement.mp3", "powerful_mario.mp3" },
chase = { "MusicChase", "pc_chase.mp3", "chase.mp3", "THE_STEPS_BEHIND_YOU__-_Horror_Mario_64.mp3", "the_steps_behind_you.mp3" },
}
local function getTrack(key)
local t = MUS.sounds[key]
if t then return t end
if t == false and os.clock() - (MUS.failAt[key] or 0) < 15 then return nil end
local list = MUS_FILES[key]
local id
for i, v in ipairs(list) do
if i == 1 then v = PC[v] end
local ok, r = pcall(resolveAudio, v)
if ok and r then id = r break end
end
if not id then
MUS.sounds[key] = false
MUS.failAt[key] = os.clock()
MUS.err[key] = "file not found: " .. tostring(PC[list[1]])
return nil
end
local snd = Instance.new("Sound")
snd.Name = "PursuitMarioMusic_" .. key
snd.Looped = true
snd.Volume = 0
snd.SoundId = id
snd.Parent = SoundService_
MUS.sounds[key] = snd
MUS.err[key] = nil
return snd
end
local function roleFromText(s)
if string.find(s, "lobby", 1, true) then return "lobby" end
if string.find(s, "termin", 1, true) or string.find(s, "killer", 1, true) then return "terminator" end
if string.find(s, "user", 1, true) or string.find(s, "usu", 1, true) or string.find(s, "survivor", 1, true) or string.find(s, "runner", 1, true) then return "user" end
return nil
end
local function roleOf(p, g)
local ch = p.Character
local hum = ch and ch:FindFirstChildOfClass("Humanoid")
if not hum or hum.Health <= 0 then return "dead" end
if p.Team then
local r = roleFromText(lowerS(p.Team.Name))
if r then return r end
end
for _, n in ipairs({ "Team", "Role", "Type", "Class" }) do
for _, h in ipairs({ p, ch }) do
local v = h:GetAttribute(n)
if type(v) == "string" then
local r = roleFromText(lowerS(v))
if r then return r end
end
end
end
local tx = textOf(ch)
if string.find(tx, "termin", 1, true) or string.find(tx, "dante", 1, true) or string.find(tx, "pony", 1, true) then return "terminator" end
return g and "user" or "unknown"
end
local function anyWithin(list, pos, range)
for _, q in ipairs(list) do
if (q - pos).Magnitude <= range then return true end
end
return false
end
local function decideMusic()
local g = detectGame()
if g == nil then g = PC.UnknownIsGame end
if not g then MUS.peak = 0 return nil end
local char = lp.Character
local myRoot = char and char:FindFirstChild("HumanoidRootPart")
local tpos, upos, nUsers, nTerm, myRole = {}, {}, 0, 0, "unknown"
for _, p in ipairs(Players_:GetPlayers()) do
local r = roleOf(p, g)
local hr = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
if p == lp then myRole = r end
if r == "terminator" then
nTerm += 1
if hr and p ~= lp then tpos[#tpos + 1] = hr.Position end
elseif r == "user" then
nUsers += 1
if hr and p ~= lp then upos[#upos + 1] = hr.Position end
end
end
for m in pairs(tracked) do
if m.Parent and not Players_:GetPlayerFromCharacter(m) then
local hum = m:FindFirstChildOfClass("Humanoid")
local hr = m:FindFirstChild("HumanoidRootPart")
if hum and hum.Health > 0 and hr then
local tx = textOf(m)
if string.find(tx, "termin", 1, true) or string.find(tx, "dante", 1, true) or string.find(tx, "pony", 1, true) then
nTerm += 1
tpos[#tpos + 1] = hr.Position
end
end
end
end
if nUsers + nTerm == 0 then MUS.peak = 0 end
if nTerm >= 1 then MUS.peak = math.max(MUS.peak, nUsers) end
if myRole == "lobby" then return nil end
if MUS.hintLMS or (nTerm >= 1 and nUsers == 1 and MUS.peak >= 2) then return "lms" end
local now = os.clock()
if myRoot and myRole ~= "dead" then
local near
if myRole == "terminator" then near = anyWithin(upos, myRoot.Position, PC.ChaseRange)
else near = anyWithin(tpos, myRoot.Position, PC.ChaseRange) end
if near then MUS.chaseUntil = now + 5 end
end
if MUS.hintChase or now < MUS.chaseUntil then return "chase" end
return nil
end
local function musicUpdate()
local want
if PC.Enabled and PC.MusicOn then
scanGameMusic()
want = MUS.force or decideMusic()
end
local snd = want and getTrack(want)
if want and not snd then want = nil end
MUS.cur = want
muteGame(want ~= nil)
if not (PC.Enabled and PC.MusicOn) then
MUS.status = "off"
elseif want then
MUS.status = (MUS.force and "TEST: " or "") .. (want == "lms" and "LMS music" or "chase music")
else
MUS.status = (MUS.err.lms or MUS.err.chase) and "missing mp3 (run the music installer once)" or "waiting (game music)"
end
end
RunService_.Heartbeat:Connect(function(dt)
for k, snd in pairs(MUS.sounds) do
if snd then
local target = (MUS.cur == k) and PC.MusicVolume or 0
local v = snd.Volume
if v ~= target then
local step = dt * (math.max(PC.MusicVolume, 0.1) / 1.2)
v = v < target and math.min(target, v + step) or math.max(target, v - step)
snd.Volume = v
end
if MUS.cur == k then
if not snd.IsPlaying then
if MUS.last ~= k then snd.TimePosition = 0 end
snd:Play()
end
elseif v == 0 and snd.IsPlaying then
snd:Stop()
end
end
end
if MUS.last ~= MUS.cur and MUS.cur ~= nil then MUS.last = MUS.cur end
if MUS.cur == nil and MUS.last ~= nil then
local allQuiet = true
for _, snd in pairs(MUS.sounds) do
if snd and snd.IsPlaying then allQuiet = false end
end
if allQuiet then MUS.last = nil end
end
end)
task.spawn(function()
while true do
task.wait(0.4)
local ok, e = pcall(musicUpdate)
if not ok then MUS.status = "music error" end
end
end)

