local refreshMenu
local function buildMenu()
local pg = lp:WaitForChild("PlayerGui")
local old = pg:FindFirstChild("PursuitCoreUI")
if old then old:Destroy() end
local g = Instance.new("ScreenGui")
g.Name = "PursuitCoreUI"
g.ResetOnSpawn = false
g.IgnoreGuiInset = true
g.DisplayOrder = 70
g.Parent = pg
local function style(b)
b.BackgroundColor3 = Color3.fromRGB(60, 60, 60)
b.BackgroundTransparency = 0.15
b.BorderSizePixel = 0
b.TextColor3 = Color3.new(1, 1, 1)
b.Font = Enum.Font.GothamBold
b.TextSize = 13
b.TextWrapped = true
Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
end
toastLabel = Instance.new("TextLabel")
toastLabel.Size = UDim2.new(0.9, 0, 0, 56)
toastLabel.Position = UDim2.new(0.05, 0, 1, -110)
toastLabel.BackgroundColor3 = Color3.fromRGB(20, 20, 30)
toastLabel.BackgroundTransparency = 0.2
toastLabel.TextColor3 = Color3.new(1, 1, 1)
toastLabel.Font = Enum.Font.GothamBold
toastLabel.TextSize = 14
toastLabel.TextWrapped = true
toastLabel.Visible = false
toastLabel.Parent = g
Instance.new("UICorner", toastLabel).CornerRadius = UDim.new(0, 10)
local open = Instance.new("TextButton")
open.Size = UDim2.fromOffset(70, 34)
open.Position = UDim2.new(1, -80, 0, 60)
open.Text = "PC"
open.Parent = g
style(open)
open.BackgroundColor3 = Color3.fromRGB(229, 37, 33)
local panel = Instance.new("ScrollingFrame")
panel.Size = UDim2.fromOffset(250, 300)
panel.Position = UDim2.new(1, -260, 0, 100)
panel.BackgroundColor3 = Color3.fromRGB(25, 25, 35)
panel.BackgroundTransparency = 0.1
panel.BorderSizePixel = 0
panel.ScrollBarThickness = 6
panel.ScrollingDirection = Enum.ScrollingDirection.Y
panel.CanvasSize = UDim2.new(0, 0, 0, 0)
panel.AutomaticCanvasSize = Enum.AutomaticSize.Y
panel.Visible = false
panel.Parent = g
Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 10)
local pad = Instance.new("UIPadding", panel)
pad.PaddingTop, pad.PaddingBottom, pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 8), UDim.new(0, 8), UDim.new(0, 8), UDim.new(0, 14)
local lay = Instance.new("UIListLayout", panel)
lay.Padding = UDim.new(0, 6)
lay.SortOrder = Enum.SortOrder.LayoutOrder
local status = Instance.new("TextLabel")
status.Size = UDim2.new(1, 0, 0, 22)
status.BackgroundTransparency = 1
status.TextColor3 = Color3.fromRGB(255, 220, 120)
status.Font = Enum.Font.GothamBold
status.TextSize = 13
status.LayoutOrder = -1
status.Parent = panel
local rows = {}
local function row(order, textFn, onClick)
local b = Instance.new("TextButton")
b.Size = UDim2.new(1, 0, 0, 32)
b.LayoutOrder = order
b.Parent = panel
style(b)
b.Activated:Connect(function() onClick(); refreshMenu() end)
rows[#rows + 1] = function() b.Text = textFn() end
end
row(0, function() return "Pursuitcore mode: " .. (PC.Enabled and "ON (tap = turn off)" or "OFF") end, function()
PC.Enabled = not PC.Enabled
if PC.Refresh then PC.Refresh() end
end)
local FACES = { "AUTO", "1 open", "2 half", "3 closed", "4 X", "5 side-eye", "6 smirk", "7 angry" }
local function onoff(v) return v and "ON" or "OFF" end
row(1, function() return "Mode: " .. string.upper(PC.Mode) end, function()
PC.Mode = PC.Mode == "auto" and "game" or (PC.Mode == "game" and "lobby" or "auto")
end)
row(2, function() return "Playable SM64 moves: " .. onoff(PC.Playable) end, function() PC.Playable = not PC.Playable end)
row(3, function() return "Dante -> Mario: " .. onoff(PC.SwapDante) end, function() PC.SwapDante = not PC.SwapDante end)
row(4, function() return "Party Pony -> Mario: " .. onoff(PC.SwapPartyPony) end, function() PC.SwapPartyPony = not PC.SwapPartyPony end)
row(5, function() return "All Terminators -> Mario: " .. onoff(PC.SwapTerminators) end, function() PC.SwapTerminators = not PC.SwapTerminators end)
row(6, function() return "Mario icons in menus: " .. onoff(PC.SwapIcons) .. (PC.SwapIcons and (" (" .. iconStatus() .. ")") or "") end, function() PC.SwapIcons = not PC.SwapIcons; iconSweepAt = -100 end)
row(7, function() return "Face: " .. FACES[(PC.FaceLock or 0) + 1] end, function()
local n = ((PC.FaceLock or 0) + 1) % 8
PC.FaceLock = n > 0 and n or nil
end)
row(10, function() return "Music (LMS / chase): " .. onoff(PC.MusicOn) end, function() PC.MusicOn = not PC.MusicOn end)
row(11, function()
local e = MUS.err.lms or MUS.err.chase
return "Music now: " .. MUS.status .. (e and PC.MusicOn and ("  (" .. e .. ")") or "")
end, function()
for _, sn in pairs(MUS.sounds) do if sn then pcall(function() sn:Destroy() end) end end
MUS.err, MUS.failAt, MUS.sounds, MUS.last = {}, {}, {}, nil
end)
local box = Instance.new("TextBox")
box.Size = UDim2.new(1, 0, 0, 120)
box.LayoutOrder = 9
box.Visible = false
box.MultiLine = true
box.TextWrapped = true
box.ClearTextOnFocus = false
box.TextXAlignment = Enum.TextXAlignment.Left
box.TextYAlignment = Enum.TextYAlignment.Top
box.Font = Enum.Font.Code
box.TextSize = 12
box.Text = ""
box.Parent = panel
style(box)
row(8, function() return box.Visible and "Hide animation names" or "Show animation names seen" end, function()
box.Visible = not box.Visible
box.Text = "Animation names the game played (copy and send these):\n" .. table.concat(shared.PursuitSeenAnims.list, "\n")
end)
local function fitPanel()
local cam = workspace.CurrentCamera
local vsY = cam and cam.ViewportSize.Y or 600
local want = lay.AbsoluteContentSize.Y + 16
panel.Size = UDim2.fromOffset(250, math.clamp(want, 60, math.max(120, vsY - 150)))
end
lay:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fitPanel)
row(12, function() return "Test music: " .. (MUS.force == "lms" and "LMS (playing)" or (MUS.force == "chase" and "CHASE (playing)" or "off")) end, function()
MUS.force = MUS.force == nil and "lms" or (MUS.force == "lms" and "chase" or nil)
end)
local mbox = Instance.new("TextBox")
mbox.Size = UDim2.new(1, 0, 0, 120)
mbox.LayoutOrder = 14
mbox.Visible = false
mbox.MultiLine = true
mbox.TextWrapped = true
mbox.ClearTextOnFocus = false
mbox.TextXAlignment = Enum.TextXAlignment.Left
mbox.TextYAlignment = Enum.TextYAlignment.Top
mbox.Font = Enum.Font.Code
mbox.TextSize = 12
mbox.Text = ""
mbox.Parent = panel
style(mbox)
row(13, function() return mbox.Visible and "Hide game music names" or "Show game music names seen" end, function()
mbox.Visible = not mbox.Visible
mbox.Text = "Game music sounds seen (copy and send these):\n" .. table.concat(MUS.seenList, "\n")
end)
refreshMenu = function()
open.Visible = PC.Enabled and true or false
if not PC.Enabled then panel.Visible = false end
status.Text = "Detected: " .. detectedText
for _, f in ipairs(rows) do f() end
fitPanel()
end
open.Activated:Connect(function()
panel.Visible = not panel.Visible
refreshMenu()
end)
refreshMenu()
end
task.spawn(function() pcall(buildMenu) end)

-- ---- main loop ----
local unknownSince = nil
local function tick()
local g = detectGame()
detectedText = g == nil and "UNKNOWN" or (g and "MATCH (Mario)" or "LOBBY (normal)")
if g == nil then
unknownSince = unknownSince or os.clock()
if os.clock() - unknownSince > 4 and not PC.toldUnknown then
PC.toldUnknown = true
toast("Pursuitcore: can't tell lobby from match. Tap PC > Mode to force Mario (GAME) or normal (LOBBY).", 10)
end
else
unknownSince = nil
end
if g == nil then g = PC.UnknownIsGame end
-- my own character
local char = lp.Character
if char and char.Parent and char:FindFirstChildOfClass("Humanoid") then
local want = nil
if not PC.Enabled then want = "play"
elseif g then want = PC.Playable and "play" or "puppet" end
local cur = REG[char]
if cur and cur.mode ~= want then cur.kill(); cur = nil end
if want and not cur and not launching[char] then launch(char, want) end
end
-- everybody else who is Dante / Party Pony
for m in pairs(tracked) do
if not m:IsDescendantOf(workspace) then
if REG[m] then REG[m].kill() end
tracked[m] = nil
elseif m ~= char then
local want = PC.Enabled and g and swapMatch(m)
local cur = REG[m]
if cur and not want then cur.kill() end
if want and not cur and not launching[m] and m:FindFirstChildOfClass("Humanoid") and m:FindFirstChild("HumanoidRootPart") then
launch(m, "puppet")
end
end
end
pcall(iconSweep)
if refreshMenu then pcall(refreshMenu) end
end
local lastEnabled = PC.Enabled
PC.Refresh = function()
iconSweepAt = -100
if PC.Enabled ~= lastEnabled then
lastEnabled = PC.Enabled
toast(PC.Enabled and "Pursuitcore mode ON. The PC button (top right) has its settings and turns it off." or "Pursuitcore mode OFF. Normal Mario script.", 7)
end
task.defer(function()
pcall(tick)
if refreshMenu then pcall(refreshMenu) end
end)
end
task.spawn(function()
while true do
task.wait(0.5)
local ok, e = pcall(tick)
if not ok then reportError("Pursuitcore error: " .. tostring(e)) end
end
end)
lp.CharacterAdded:Connect(function() task.defer(function() pcall(tick) end) end)
task.defer(function() pcall(tick) end)
